#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SyntaxGeneratedCodecArtifact {
    pub target: &'static str,
    pub source: String,
    pub metadata: Value,
    pub metadata_sha256: String,
}

pub fn build_registered_parser_backed_syntax_generated_codec_artifact(
    grammar_id: &str,
) -> Result<SyntaxGeneratedCodecArtifact, SyntaxBackendBoundaryError> {
    let entry = syntax_codec_registry_entry(grammar_id).ok_or_else(|| {
        SyntaxBackendBoundaryError::new(
            "syntax_codec_registry.grammar_id",
            format!("grammar {grammar_id} is not registered in the syntax codec registry"),
        )
    })?;
    build_parser_backed_syntax_generated_codec_artifact(entry)
}

pub fn build_parser_backed_syntax_generated_codec_artifact(
    entry: &SyntaxCodecRegistryEntry,
) -> Result<SyntaxGeneratedCodecArtifact, SyntaxBackendBoundaryError> {
    let (grammar, sidecar) = lower_registered_parser_backed_syntax_entry(entry)?;
    let source = render_registered_syntax_codec_fixture(entry, &sidecar)?;
    let generation_options = json!({
        "renderer": entry.renderer()?,
        "renderer_version": 1,
        "crate_name": entry.crate_name()?,
        "crate_target": "bin",
        "compiler_path": "sidecar-only",
    });
    let mut metadata = syntax_generated_codec_metadata(
        entry.target_id,
        &grammar,
        &sidecar,
        &source,
        &generation_options,
    );
    metadata["syntax_codec_registry_entry"] = json!({
        "target_id": entry.target_id,
        "grammar_id": entry.grammar_id,
        "metadata_path": entry.metadata_path,
        "completed_promotion_class": entry.completed_promotion_class,
        "generated_test_markers": entry.generated_test_markers,
        "renderer_family": entry.renderer_family()?,
        "renderer": entry.renderer()?,
        "crate_name": entry.crate_name()?,
        "construct_class": entry.construct_class(),
    });
    let metadata_sha256 = json_sha256(&metadata).map_err(|error| {
        SyntaxBackendBoundaryError::new(
            "syntax_codec_registry.metadata",
            format!("failed to hash parser-backed syntax codec metadata: {error}"),
        )
    })?;

    Ok(SyntaxGeneratedCodecArtifact {
        target: entry.target_id,
        source,
        metadata,
        metadata_sha256,
    })
}

pub fn build_toy_syntax_generated_codec_artifact() -> SyntaxGeneratedCodecArtifact {
    let spec = ToyGrammarSpec::assignment_language_v1();
    let grammar = spec.to_grammar_ir();
    let sidecar = lower_grammar_ir_to_structural_model(
        &grammar,
        GrammarStructuralTokenLayout::from_toy_assignment(&spec.layout),
    )
    .unwrap();
    let source = render_toy_syntax_codec_fixture(&sidecar);
    let generation_options = json!({
        "renderer": "render_toy_syntax_codec_fixture",
        "renderer_version": 1,
        "crate_name": "toy-syntax-generated-codec",
        "crate_target": "bin",
        "compiler_path": "sidecar-only",
    });
    let metadata =
        syntax_generated_codec_metadata("toy", &grammar, &sidecar, &source, &generation_options);
    let metadata_sha256 =
        json_sha256(&metadata).expect("failed to hash syntax codec reproducibility metadata");

    SyntaxGeneratedCodecArtifact {
        target: "toy",
        source,
        metadata,
        metadata_sha256,
    }
}

