pub fn syntax_generated_codec_metadata(
    target: &str,
    grammar: &GrammarIr,
    sidecar: &GrammarStructuralModelSidecar,
    source: &str,
    generation_options: &Value,
) -> Value {
    let token_layout = &sidecar.structural_model.token_ranges;
    let boundary_manifest = syntax_structural_model_boundary_manifest();
    let envelope = syntax_backend_generated_artifact_envelope();
    let validation_hook_contract = syntax_backend_validation_hook_contract(&envelope);
    let input_diagnostics_contract =
        syntax_backend_input_diagnostics_contract(&validation_hook_contract);
    let input_diagnostics_negative_fixture =
        syntax_backend_input_diagnostics_negative_fixture(&input_diagnostics_contract);
    let api_boundary = syntax_backend_generator_api_boundary();
    let rendered_source_sha256 = sha256_hex(source.as_bytes());
    let generated_crate_identity = json!({
        "crate_name": generation_options["crate_name"].clone(),
        "crate_target": generation_options["crate_target"].clone(),
        "renderer": generation_options["renderer"].clone(),
    });
    let generated_crate_identity_sha256 = json_sha256(&generated_crate_identity)
        .expect("failed to hash syntax codec generated crate identity");
    let grammar_input_sha256 =
        json_sha256(grammar).expect("failed to hash syntax codec grammar input");
    let mut source_metadata_provenance = json!({
        "source_kind": &grammar.provenance.source_kind,
        "source_path": &grammar.provenance.source_path,
        "source_sha256": &grammar.provenance.source_sha256,
        "metadata_path": &grammar.provenance.metadata_path,
        "metadata_sha256": &grammar.provenance.metadata_sha256,
        "parser": &grammar.provenance.parser,
    });
    source_metadata_provenance["sha256"] = json!(
        json_sha256(&source_metadata_provenance)
            .expect("failed to hash syntax codec source metadata provenance")
    );
    let boundary_handoff =
        boundary_manifest_handoff_metadata(target, grammar, sidecar, &boundary_manifest);
    let generated_artifact_envelope =
        generated_artifact_envelope_handoff_metadata(target, &envelope);
    let validation_hook_handoff =
        validation_hook_contract_handoff_metadata(target, sidecar, &validation_hook_contract);
    let validation_hook_sidecar_evidence =
        syntax_backend_validation_hook_sidecar_evidence(&validation_hook_contract);
    let validation_hook_sidecar_evidence_handoff =
        validation_hook_sidecar_evidence_handoff_metadata(
            target,
            sidecar,
            &validation_hook_contract,
            &validation_hook_sidecar_evidence,
        );
    let input_diagnostics_handoff =
        input_diagnostics_contract_handoff_metadata(target, sidecar, &input_diagnostics_contract);
    let input_diagnostics_negative_handoff = input_diagnostics_negative_fixture_handoff_metadata(
        target,
        &input_diagnostics_contract,
        &input_diagnostics_negative_fixture,
    );
    let token_layout_metadata = token_layout_envelope_metadata(token_layout);
    let structural_model_sha256 = json_sha256(&sidecar.structural_model)
        .expect("failed to hash syntax codec structural model");
    let token_layout_sha256 =
        json_sha256(token_layout).expect("failed to hash syntax codec token layout");
    let generation_options_sha256 =
        json_sha256(generation_options).expect("failed to hash syntax codec generation options");
    let generated_artifact_replay = syntax_backend_generated_artifact_replay(
        &envelope,
        &validation_hook_sidecar_evidence,
        &input_diagnostics_contract,
        &input_diagnostics_negative_fixture,
    );
    let generated_artifact_replay_handoff = generated_artifact_replay_handoff_metadata(
        target,
        &generated_artifact_replay,
        &rendered_source_sha256,
        &validation_hook_handoff["validation_hook_provenance"]["source_or_metadata_sha256"],
        &validation_hook_handoff["validation_hook_provenance"]["parser_or_grammar_identity"],
        &grammar_input_sha256,
        &source_metadata_provenance["sha256"],
        &structural_model_sha256,
        &token_layout_sha256,
        &generated_crate_identity_sha256,
        &generation_options_sha256,
        &generated_artifact_envelope["canonical_sha256"],
        &validation_hook_sidecar_evidence_handoff["canonical_sha256"],
        &input_diagnostics_handoff["canonical_sha256"],
        &input_diagnostics_negative_handoff["canonical_sha256"],
        &boundary_handoff["sha256"],
        &boundary_handoff["target"]["target_manifest_sha256"],
        parser_backed_construct_specific_sidecar(sidecar),
    );
    let metadata = json!({
        "artifact_kind": "tct_syntax_generated_codec_reproducibility_metadata",
        "artifact_version": 1,
        "tool": TOOL,
        "version": VERSION,
        "completed_promotion_class": COMPLETED_PROMOTION_CLASS,
        "next_missing_stable_promotion_class": NEXT_MISSING_STABLE_PROMOTION_CLASS,
        "api_version": api_boundary.api_version,
        "source_contract": api_boundary.source_contract,
        "compiler_boundary": api_boundary.compiler_boundary,
        "inputs": api_boundary.inputs,
        "outputs": api_boundary.outputs,
        "rendered_source": {
            "language": "rust",
            "bytes": source.len(),
            "sha256": rendered_source_sha256.clone(),
        },
        "rendered_source_sha256": rendered_source_sha256,
        "grammar_input": {
            "grammar_id": &grammar.grammar_id,
            "grammar_ir_version": grammar.version,
            "sha256": grammar_input_sha256,
        },
        "structural_model": {
            "frontend_id": &sidecar.structural_model.frontend_id,
            "model_id": &sidecar.structural_model.model_id,
            "model_version": &sidecar.model_version,
            "sha256": structural_model_sha256.clone(),
        },
        "structural_model_sha256": structural_model_sha256,
        "boundary_manifest": boundary_handoff.clone(),
        "boundary_manifest_sha256": boundary_handoff["sha256"].clone(),
        "target_manifest_sha256": boundary_handoff["target"]["target_manifest_sha256"].clone(),
        "source_metadata_provenance": source_metadata_provenance.clone(),
        "source_metadata_provenance_sha256": source_metadata_provenance["sha256"].clone(),
        "token_layout": {
            "sha256": token_layout_sha256.clone(),
            "vocab_size": token_layout.vocab_size,
            "pad_token": token_layout.pad_token,
            "raw_base_vocab_size": token_layout.raw_base_vocab_size(),
            "structural_ranges": token_layout_metadata["structural_ranges"].clone(),
            "payload_ranges": token_layout_metadata["payload_ranges"].clone(),
            "bpe_boundary": token_layout_metadata["bpe_boundary"].clone(),
            "ranges": &token_layout.ranges,
        },
        "token_layout_sha256": token_layout_sha256,
        "generated_crate": generated_crate_identity,
        "generated_crate_identity": {
            "sha256": generated_crate_identity_sha256,
            "crate_name": generation_options["crate_name"].clone(),
            "crate_target": generation_options["crate_target"].clone(),
            "renderer": generation_options["renderer"].clone(),
        },
        "generation_options": generation_options,
        "generation_options_sha256": generation_options_sha256,
        "generated_artifact_envelope": generated_artifact_envelope.clone(),
        "validation_hook_contract": validation_hook_handoff.clone(),
        "validation_hook_contract_sha256": validation_hook_handoff["canonical_sha256"].clone(),
        "validation_hook_sidecar_evidence": validation_hook_sidecar_evidence_handoff.clone(),
        "validation_hook_sidecar_evidence_sha256": validation_hook_sidecar_evidence_handoff["canonical_sha256"].clone(),
        "generated_artifact_replay": generated_artifact_replay_handoff.clone(),
        "generated_artifact_replay_sha256": generated_artifact_replay_handoff["canonical_sha256"].clone(),
        "input_diagnostics_contract": input_diagnostics_handoff.clone(),
        "input_diagnostics_contract_sha256": input_diagnostics_handoff["canonical_sha256"].clone(),
        "input_diagnostics_negative_fixture": input_diagnostics_negative_handoff.clone(),
        "input_diagnostics_negative_fixture_sha256": input_diagnostics_negative_handoff["canonical_sha256"].clone(),
        "generated_codec_artifact_metadata": {
            "target": target,
            "surface": "generated_codec_artifact_metadata",
            "envelope_path": GENERATED_ARTIFACT_ENVELOPE_PATH,
            "envelope_fixture_sha256": generated_artifact_envelope["fixture_sha256"].clone(),
            "validation_hook_contract_path": VALIDATION_HOOK_CONTRACT_PATH,
            "validation_hook_contract_fixture_sha256": validation_hook_handoff["fixture_sha256"].clone(),
            "validation_hook_sidecar_evidence_path": VALIDATION_HOOK_SIDECAR_EVIDENCE_PATH,
            "validation_hook_sidecar_evidence_fixture_sha256": validation_hook_sidecar_evidence_handoff["fixture_sha256"].clone(),
            "generated_artifact_replay_path": GENERATED_ARTIFACT_REPLAY_PATH,
            "generated_artifact_replay_fixture_sha256": generated_artifact_replay_handoff["fixture_sha256"].clone(),
            "input_diagnostics_contract_path": INPUT_DIAGNOSTICS_CONTRACT_PATH,
            "input_diagnostics_contract_fixture_sha256": input_diagnostics_handoff["fixture_sha256"].clone(),
            "input_diagnostics_negative_fixture_path": INPUT_DIAGNOSTICS_NEGATIVE_FIXTURE_PATH,
            "input_diagnostics_negative_fixture_fixture_sha256": input_diagnostics_negative_handoff["fixture_sha256"].clone(),
            "required_fields": envelope.artifact_metadata.required_fields,
            "provenance_hashes": envelope.provenance_hashes.required,
            "persistence_policy": generated_artifact_envelope["persistence_policy"].clone(),
            "decode_policy": generated_artifact_envelope["decode_policy"].clone(),
            "token_layout_metadata": generated_artifact_envelope["token_layout_metadata"].clone(),
            "validation_hook_contract": {
                "target": target,
                "validation_surfaces": validation_hook_handoff["validation_surfaces"].clone(),
                "source_reparse_or_equivalent_check": validation_hook_handoff["source_reparse_or_equivalent_check"].clone(),
                "renderer_formatter_status": validation_hook_handoff["renderer_formatter_status"].clone(),
                "external_check_policy": validation_hook_handoff["external_check_policy"].clone(),
                "validation_hook_provenance": validation_hook_handoff["validation_hook_provenance"].clone(),
                "non_goals": validation_hook_handoff["non_goals"].clone(),
            },
            "validation_hook_sidecar_evidence": {
                "target": target,
                "record": validation_hook_sidecar_evidence_handoff["record"].clone(),
                "source_validation_hook_contract": validation_hook_sidecar_evidence_handoff["source_validation_hook_contract"].clone(),
                "sidecar_status": validation_hook_sidecar_evidence_handoff["sidecar_status"].clone(),
                "compiler_boundary": validation_hook_sidecar_evidence_handoff["compiler_boundary"].clone(),
                "validation_hook_contract_sha256": validation_hook_sidecar_evidence_handoff["validation_hook_contract_sha256"].clone(),
                "non_goals": validation_hook_sidecar_evidence_handoff["non_goals"].clone(),
            },
            "generated_artifact_replay": {
                "target": target,
                "record": generated_artifact_replay_handoff["record"].clone(),
                "deterministic_hash_fields": generated_artifact_replay_handoff["deterministic_hash_fields"].clone(),
                "volatile_report_policy": generated_artifact_replay_handoff["volatile_report_policy"].clone(),
                "compiler_boundary": generated_artifact_replay_handoff["compiler_boundary"].clone(),
                "source_fixture_hashes": generated_artifact_replay_handoff["source_fixture_hashes"].clone(),
            },
            "input_diagnostics_contract": {
                "target": target,
                "input_surface": input_diagnostics_handoff["input_surface"].clone(),
                "diagnostic_shape": input_diagnostics_handoff["diagnostic_shape"].clone(),
                "unsupported_syntax_error_shape": input_diagnostics_handoff["unsupported_syntax_error_shape"].clone(),
                "diagnostics_provenance": input_diagnostics_handoff["diagnostics_provenance"].clone(),
                "sidecar_status": input_diagnostics_handoff["sidecar_status"].clone(),
                "non_goals": input_diagnostics_handoff["non_goals"].clone(),
            },
            "input_diagnostics_negative_fixture": {
                "target": target,
                "coverage_scope": input_diagnostics_negative_handoff["coverage_scope"].clone(),
                "fixture_target_ids": input_diagnostics_negative_handoff["fixture_target_ids"].clone(),
                "fixture_ids": input_diagnostics_negative_handoff["fixture_ids"].clone(),
                "fixture_kinds": input_diagnostics_negative_handoff["fixture_kinds"].clone(),
                "diagnostic_severities": input_diagnostics_negative_handoff["diagnostic_severities"].clone(),
                "rule_path_evidence": input_diagnostics_negative_handoff["rule_path_evidence"].clone(),
                "unsupported_syntax_errors": input_diagnostics_negative_handoff["unsupported_syntax_errors"].clone(),
                "source_or_metadata_sha256": input_diagnostics_negative_handoff["source_or_metadata_sha256"].clone(),
                "parser_or_grammar_identity": input_diagnostics_negative_handoff["parser_or_grammar_identity"].clone(),
                "sidecar_boundary_sha256": input_diagnostics_negative_handoff["sidecar_boundary_sha256"].clone(),
                "diagnostic_contract_sha256": input_diagnostics_negative_handoff["diagnostic_contract_sha256"].clone(),
                "sidecar_status": input_diagnostics_negative_handoff["sidecar_status"].clone(),
                "non_goals": input_diagnostics_negative_handoff["non_goals"].clone(),
            },
        },
        "sidecar_boundary": {
            "generated_json_schema_output_changed": sidecar
                .structural_model
                .boundary
                .generated_json_schema_output_changed,
            "core_compiler_path_changed": sidecar.structural_model.boundary.core_compiler_path_changed,
            "production_grammar_compiler_path_changed": sidecar
                .structural_model
                .boundary
                .production_grammar_compiler_path_changed,
        },
    });
    metadata
}

pub fn syntax_structural_model_boundary_manifest() -> Value {
    let repo_root = Path::new(env!("CARGO_MANIFEST_DIR"));
    let manifest_path = repo_root.join(STRUCTURAL_MODEL_BOUNDARY_MANIFEST_PATH);
    serde_json::from_slice(
        &fs::read(&manifest_path).expect("failed to read syntax StructuralModel manifest"),
    )
    .expect("failed to parse syntax StructuralModel manifest")
}

pub fn syntax_backend_generator_api_boundary() -> SyntaxGeneratorApiBoundary {
    let contract: SyntaxBackendProductionBoundaryContract =
        serde_json::from_str(PRODUCTION_BOUNDARY_CONTRACT_FIXTURE)
            .expect("production boundary contract fixture must parse");
    contract
        .production_generator_api_boundary()
        .expect("production boundary contract fixture should produce API boundary")
}

pub fn syntax_backend_generated_artifact_envelope() -> SyntaxGeneratedArtifactEnvelope {
    let api_boundary = syntax_backend_generator_api_boundary();
    let envelope: SyntaxGeneratedArtifactEnvelope =
        serde_json::from_str(GENERATED_ARTIFACT_ENVELOPE_FIXTURE)
            .expect("generated artifact envelope fixture must parse");
    envelope
        .validate_against_api_boundary(&api_boundary)
        .expect("generated artifact envelope fixture should match API boundary");
    envelope
}

pub fn syntax_backend_validation_hook_contract(
    envelope: &SyntaxGeneratedArtifactEnvelope,
) -> SyntaxValidationHookContract {
    let contract: SyntaxValidationHookContract =
        serde_json::from_str(VALIDATION_HOOK_CONTRACT_FIXTURE)
            .expect("validation hook contract fixture must parse");
    contract
        .validate_against_artifact_envelope(envelope)
        .expect("validation hook contract fixture should match generated artifact envelope");
    contract
}

pub fn syntax_backend_validation_hook_sidecar_evidence(
    contract: &SyntaxValidationHookContract,
) -> SyntaxValidationHookSidecarEvidence {
    let evidence: SyntaxValidationHookSidecarEvidence =
        serde_json::from_str(VALIDATION_HOOK_SIDECAR_EVIDENCE_FIXTURE)
            .expect("validation hook sidecar evidence fixture must parse");
    evidence
        .validate_against_contract(contract)
        .expect("validation hook sidecar evidence fixture should match contract");
    evidence
}

pub fn syntax_backend_input_diagnostics_contract(
    validation_hook_contract: &SyntaxValidationHookContract,
) -> SyntaxInputDiagnosticsContract {
    let contract: SyntaxInputDiagnosticsContract =
        serde_json::from_str(INPUT_DIAGNOSTICS_CONTRACT_FIXTURE)
            .expect("input diagnostics contract fixture must parse");
    contract
        .validate_against_validation_hook_contract(validation_hook_contract)
        .expect("input diagnostics contract fixture should match validation hook contract");
    contract
}

pub fn syntax_backend_input_diagnostics_negative_fixture(
    contract: &SyntaxInputDiagnosticsContract,
) -> SyntaxInputDiagnosticsNegativeFixtureGate {
    let fixture: SyntaxInputDiagnosticsNegativeFixtureGate =
        serde_json::from_str(INPUT_DIAGNOSTICS_NEGATIVE_FIXTURE)
            .expect("input diagnostics negative fixture must parse");
    fixture
        .validate_against_contract(contract)
        .expect("input diagnostics negative fixture should match diagnostics contract");
    fixture
}

pub fn syntax_backend_generated_artifact_replay(
    envelope: &SyntaxGeneratedArtifactEnvelope,
    sidecar_evidence: &SyntaxValidationHookSidecarEvidence,
    input_diagnostics_contract: &SyntaxInputDiagnosticsContract,
    input_diagnostics_negative_fixture: &SyntaxInputDiagnosticsNegativeFixtureGate,
) -> SyntaxGeneratedArtifactReproducibilityReplay {
    let replay: SyntaxGeneratedArtifactReproducibilityReplay =
        serde_json::from_str(GENERATED_ARTIFACT_REPLAY_FIXTURE)
            .expect("generated artifact replay fixture must parse");
    replay
        .validate_against_sources(
            envelope,
            sidecar_evidence,
            input_diagnostics_contract,
            input_diagnostics_negative_fixture,
        )
        .expect("generated artifact replay fixture should match source sidecar contracts");
    replay
}

fn generated_artifact_envelope_handoff_metadata(
    target: &str,
    envelope: &SyntaxGeneratedArtifactEnvelope,
) -> Value {
    assert!(
        envelope
            .artifact_metadata
            .target_ids
            .iter()
            .any(|target_id| target_id == target),
        "generated artifact envelope must cover syntax target {target}"
    );

    json!({
        "path": GENERATED_ARTIFACT_ENVELOPE_PATH,
        "artifact_kind": envelope.artifact_kind,
        "artifact_version": envelope.version,
        "api_version": envelope.api_version,
        "fixture_sha256": sha256_hex(GENERATED_ARTIFACT_ENVELOPE_FIXTURE.as_bytes()),
        "canonical_sha256": json_sha256(envelope)
            .expect("failed to hash syntax generated artifact envelope"),
        "source_api_boundary": &envelope.source_api_boundary,
        "target": target,
        "target_ids": &envelope.artifact_metadata.target_ids,
        "metadata_surface": &envelope.artifact_metadata.surface,
        "metadata_required_fields": &envelope.artifact_metadata.required_fields,
        "provenance_hashes": &envelope.provenance_hashes.required,
        "persistence_policy": &envelope.persistence_policy,
        "decode_policy": &envelope.decode_policy,
        "token_layout_metadata": &envelope.token_layout_metadata,
        "compiler_boundary": &envelope.compiler_boundary,
        "completed_promotion_class": &envelope.completed_promotion_class,
        "next_missing_stable_promotion_class": &envelope.next_missing_stable_promotion_class,
    })
}

fn validation_hook_contract_handoff_metadata(
    target: &str,
    sidecar: &GrammarStructuralModelSidecar,
    contract: &SyntaxValidationHookContract,
) -> Value {
    assert!(
        contract
            .target_ids
            .iter()
            .any(|target_id| target_id == target),
        "validation hook contract must cover syntax target {target}"
    );
    let source_check = contract
        .source_reparse_or_equivalent_checks
        .checks
        .iter()
        .find(|check| check.target == target)
        .unwrap_or_else(|| panic!("missing validation hook source check for target {target}"));
    let validation_hook_ids = sidecar
        .structural_model
        .validation_hooks
        .iter()
        .map(|hook| hook.id.clone())
        .collect::<Vec<_>>();
    let validation_hooks = sidecar
        .structural_model
        .validation_hooks
        .iter()
        .map(|hook| {
            json!({
                "id": &hook.id,
                "owner": &hook.owner,
                "runs_in_generated_hot_path": hook.runs_in_generated_hot_path,
            })
        })
        .collect::<Vec<_>>();
    let source_or_metadata_sha256 = syntax_source_or_metadata_sha256(sidecar);
    let parser_or_grammar_identity = syntax_parser_or_grammar_identity(sidecar);
    let external_check_policy_sha256 = json_sha256(&contract.external_check_policy)
        .expect("failed to hash syntax validation external check policy");
    let validation_hook_ids_sha256 =
        json_sha256(&validation_hook_ids).expect("failed to hash syntax validation hook ids");
    let renderer_metadata_sha256 = json_sha256(&sidecar.structural_model.renderer_metadata)
        .expect("failed to hash syntax validation renderer metadata");
    let sidecar_boundary_sha256 = json_sha256(&sidecar.structural_model.boundary)
        .expect("failed to hash syntax validation sidecar boundary");

    json!({
        "path": VALIDATION_HOOK_CONTRACT_PATH,
        "artifact_kind": &contract.artifact_kind,
        "artifact_version": contract.version,
        "api_version": &contract.api_version,
        "fixture_sha256": sha256_hex(VALIDATION_HOOK_CONTRACT_FIXTURE.as_bytes()),
        "canonical_sha256": json_sha256(contract)
            .expect("failed to hash syntax validation hook contract"),
        "source_artifact_envelope": &contract.source_artifact_envelope,
        "target": target,
        "target_ids": &contract.target_ids,
        "validation_surfaces": &contract.validation_surfaces,
        "source_reparse_or_equivalent_check": {
            "required": contract.source_reparse_or_equivalent_checks.required,
            "target": &source_check.target,
            "check_kind": &source_check.check_kind,
            "sidecar_evidence": &source_check.sidecar_evidence,
        },
        "renderer_formatter_status": {
            "contract": &contract.renderer_formatter_status,
            "renderer_metadata": &sidecar.structural_model.renderer_metadata,
            "renderer_metadata_sha256": renderer_metadata_sha256,
        },
        "external_check_policy": {
            "policy": &contract.external_check_policy,
            "sha256": external_check_policy_sha256,
        },
        "validation_hook_provenance": {
            "required_fields": &contract.provenance_fields,
            "target_id": target,
            "source_or_metadata_sha256": source_or_metadata_sha256,
            "parser_or_grammar_identity": parser_or_grammar_identity,
            "renderer_metadata_id": &sidecar.structural_model.renderer_metadata.id,
            "validation_hook_ids": validation_hook_ids,
            "validation_hook_ids_sha256": validation_hook_ids_sha256,
            "validation_hooks": validation_hooks,
            "external_check_policy_sha256": external_check_policy_sha256,
            "sidecar_boundary_sha256": sidecar_boundary_sha256,
        },
        "compiler_boundary": &contract.compiler_boundary,
        "non_goals": &contract.non_goals,
        "completed_promotion_class": &contract.completed_promotion_class,
        "next_missing_stable_promotion_class": &contract.next_missing_stable_promotion_class,
    })
}

fn validation_hook_sidecar_evidence_handoff_metadata(
    target: &str,
    sidecar: &GrammarStructuralModelSidecar,
    contract: &SyntaxValidationHookContract,
    evidence: &SyntaxValidationHookSidecarEvidence,
) -> Value {
    assert!(
        evidence
            .target_ids
            .iter()
            .any(|target_id| target_id == target),
        "validation hook sidecar evidence must cover syntax target {target}"
    );
    let record = evidence
        .records
        .iter()
        .find(|record| record.target_id == target)
        .unwrap_or_else(|| {
            panic!("missing validation hook sidecar evidence record for target {target}")
        });
    let source_or_metadata_sha256 = syntax_source_or_metadata_sha256(sidecar);
    let parser_or_grammar_identity = syntax_parser_or_grammar_identity(sidecar);
    let sidecar_boundary = json!(&sidecar.structural_model.boundary);
    let validation_hook_ids = sidecar
        .structural_model
        .validation_hooks
        .iter()
        .map(|hook| hook.id.clone())
        .collect::<Vec<_>>();

    let record_value = if let Some(construct) = parser_backed_construct_specific_sidecar(sidecar) {
        json!({
            "target_id": target,
            "source_or_metadata_sha256": source_or_metadata_sha256,
            "parser_or_grammar_identity": parser_or_grammar_identity,
            "renderer_metadata_id": &sidecar.structural_model.renderer_metadata.id,
            "renderer_formatter_status": &record.renderer_formatter_status,
            "validation_hook_ids": validation_hook_ids,
            "validation_hook_ids_sha256": json_sha256(&validation_hook_ids)
                .expect("failed to hash construct-specific validation hook ids"),
            "external_check_policy_sha256": &record.external_check_policy_sha256,
            "validation_hook_contract_sha256": &record.validation_hook_contract_sha256,
            "sidecar_boundary": sidecar_boundary,
            "sidecar_boundary_sha256": json_sha256(&sidecar.structural_model.boundary)
                .expect("failed to hash construct-specific sidecar boundary"),
            "sidecar_command_identity": &record.sidecar_command_identity,
            "construct_specific_sidecar": construct,
        })
    } else {
        assert_eq!(record.source_or_metadata_sha256, source_or_metadata_sha256);
        assert_eq!(
            json!(&record.parser_or_grammar_identity),
            parser_or_grammar_identity
        );
        assert_eq!(
            record.renderer_metadata_id,
            sidecar.structural_model.renderer_metadata.id
        );
        assert_eq!(record.validation_hook_ids, validation_hook_ids);
        assert_eq!(
            json!(&record.sidecar_boundary),
            sidecar_boundary,
            "sidecar evidence boundary must match generated-code sidecar boundary"
        );
        json!(record)
    };

    let canonical_sha256 =
        json_sha256(evidence).expect("failed to hash validation hook sidecar evidence");
    let validation_hook_contract_sha256 =
        json_sha256(contract).expect("failed to hash validation hook source contract");

    json!({
        "path": VALIDATION_HOOK_SIDECAR_EVIDENCE_PATH,
        "artifact_kind": &evidence.artifact_kind,
        "artifact_version": evidence.version,
        "api_version": &evidence.api_version,
        "fixture_sha256": sha256_hex(VALIDATION_HOOK_SIDECAR_EVIDENCE_FIXTURE.as_bytes()),
        "canonical_sha256": canonical_sha256,
        "source_validation_hook_contract": &evidence.source_validation_hook_contract,
        "validation_hook_contract_sha256": validation_hook_contract_sha256,
        "target": target,
        "target_ids": &evidence.target_ids,
        "record": record_value,
        "sidecar_command_identity": &record.sidecar_command_identity,
        "sidecar_status": &evidence.sidecar_status,
        "compiler_boundary": &evidence.compiler_boundary,
        "non_goals": [
            "no TctCompiler route",
            "no generated JSON Schema output change",
            "no external parser or formatter stable promotion",
            "no live toolchain requirement for fixture validation",
            "no generated hot path external checks",
        ],
        "completed_promotion_class": &evidence.completed_promotion_class,
        "next_missing_stable_promotion_class": &evidence.next_missing_stable_promotion_class,
    })
}

#[allow(clippy::too_many_arguments)]
fn generated_artifact_replay_handoff_metadata(
    target: &str,
    replay: &SyntaxGeneratedArtifactReproducibilityReplay,
    rendered_source_sha256: &str,
    source_or_metadata_sha256: &Value,
    parser_or_grammar_identity: &Value,
    grammar_input_sha256: &str,
    source_metadata_provenance_sha256: &Value,
    structural_model_sha256: &str,
    token_layout_sha256: &str,
    generated_crate_identity_sha256: &str,
    generation_options_sha256: &str,
    generated_artifact_envelope_sha256: &Value,
    validation_hook_sidecar_evidence_sha256: &Value,
    input_diagnostics_contract_sha256: &Value,
    input_diagnostics_negative_fixture_sha256: &Value,
    boundary_manifest_sha256: &Value,
    target_manifest_sha256: &Value,
    construct_specific_sidecar: Option<&str>,
) -> Value {
    assert!(
        replay
            .target_ids
            .iter()
            .any(|target_id| target_id == target),
        "generated artifact replay must cover syntax target {target}"
    );
    let record = replay
        .records
        .iter()
        .find(|record| record.target_id == target)
        .unwrap_or_else(|| panic!("missing generated artifact replay record for target {target}"));
    let expected_report_path = if target == "toy" {
        TOY_REPORT_PATH
    } else {
        PARSER_BACKED_REPORT_PATH
    };
    let expected_report_artifact_kind = if target == "toy" {
        TOY_REPORT_ARTIFACT_KIND
    } else {
        PARSER_BACKED_REPORT_ARTIFACT_KIND
    };

    assert!(record.compiler_boundary_status.syntax_frontend_only);
    assert!(!record.compiler_boundary_status.uses_json_schema_compiler);
    assert!(!record.compiler_boundary_status.uses_tct_codegen);
    assert!(!record.compiler_boundary_status.stable_tct_backend_route);
    assert!(record.compiler_boundary_status.sidecar_artifact_only);
    let source_matches =
        record.source_or_metadata_sha256 == source_or_metadata_sha256.as_str().unwrap();
    let record_value = if source_matches {
        assert_eq!(record.report_path, expected_report_path);
        assert_eq!(record.report_artifact_kind, expected_report_artifact_kind);
        assert_eq!(record.rendered_source_sha256, rendered_source_sha256);
        assert_eq!(
            json!(&record.parser_or_grammar_identity),
            parser_or_grammar_identity.clone()
        );
        assert_eq!(record.grammar_input_sha256, grammar_input_sha256);
        assert_eq!(
            record.source_metadata_provenance_sha256,
            source_metadata_provenance_sha256.as_str().unwrap()
        );
        assert_eq!(record.structural_model_sha256, structural_model_sha256);
        assert_eq!(record.token_layout_sha256, token_layout_sha256);
        assert_eq!(
            record.generated_crate_identity_sha256,
            generated_crate_identity_sha256
        );
        assert_eq!(record.generation_options_sha256, generation_options_sha256);
        assert_eq!(
            record.generated_artifact_envelope_sha256,
            generated_artifact_envelope_sha256.as_str().unwrap()
        );
        assert_eq!(
            record.validation_hook_sidecar_evidence_sha256,
            validation_hook_sidecar_evidence_sha256.as_str().unwrap()
        );
        assert_eq!(
            record.input_diagnostics_contract_sha256,
            input_diagnostics_contract_sha256.as_str().unwrap()
        );
        assert_eq!(
            record.input_diagnostics_negative_fixture_sha256,
            input_diagnostics_negative_fixture_sha256.as_str().unwrap()
        );
        assert_eq!(
            record.boundary_manifest_sha256,
            boundary_manifest_sha256.as_str().unwrap()
        );
        assert_eq!(
            record.target_manifest_sha256,
            target_manifest_sha256.as_str().unwrap()
        );
        json!(record)
    } else {
        let construct = construct_specific_sidecar
            .expect("construct-specific sidecar must name replay handoff divergence");
        json!({
            "target_id": target,
            "report_path": expected_report_path,
            "report_artifact_kind": expected_report_artifact_kind,
            "rendered_source_sha256": rendered_source_sha256,
            "source_or_metadata_sha256": source_or_metadata_sha256,
            "parser_or_grammar_identity": parser_or_grammar_identity,
            "grammar_input_sha256": grammar_input_sha256,
            "source_metadata_provenance_sha256": source_metadata_provenance_sha256,
            "structural_model_sha256": structural_model_sha256,
            "token_layout_sha256": token_layout_sha256,
            "generated_crate_identity_sha256": generated_crate_identity_sha256,
            "generation_options_sha256": generation_options_sha256,
            "generated_artifact_envelope_sha256": generated_artifact_envelope_sha256,
            "validation_hook_sidecar_evidence_sha256": validation_hook_sidecar_evidence_sha256,
            "input_diagnostics_contract_sha256": input_diagnostics_contract_sha256,
            "input_diagnostics_negative_fixture_sha256": input_diagnostics_negative_fixture_sha256,
            "boundary_manifest_sha256": boundary_manifest_sha256,
            "target_manifest_sha256": target_manifest_sha256,
            "compiler_boundary_status": &record.compiler_boundary_status,
            "construct_specific_sidecar": construct,
        })
    };

    json!({
        "path": GENERATED_ARTIFACT_REPLAY_PATH,
        "artifact_kind": &replay.artifact_kind,
        "artifact_version": replay.version,
        "tool": &replay.tool,
        "api_version": &replay.api_version,
        "fixture_sha256": sha256_hex(GENERATED_ARTIFACT_REPLAY_FIXTURE.as_bytes()),
        "canonical_sha256": json_sha256(replay)
            .expect("failed to hash syntax generated artifact replay fixture"),
        "source_generated_artifact_envelope": &replay.source_generated_artifact_envelope,
        "source_validation_hook_sidecar_evidence": &replay.source_validation_hook_sidecar_evidence,
        "source_input_diagnostics_contract": &replay.source_input_diagnostics_contract,
        "source_input_diagnostics_negative_fixture": &replay.source_input_diagnostics_negative_fixture,
        "target": target,
        "target_ids": &replay.target_ids,
        "volatile_report_policy": &replay.volatile_report_policy,
        "deterministic_hash_fields": &replay.deterministic_hash_fields,
        "record": record_value,
        "source_fixture_hashes": {
            "generated_artifact_envelope_sha256": generated_artifact_envelope_sha256.clone(),
            "validation_hook_sidecar_evidence_sha256": validation_hook_sidecar_evidence_sha256.clone(),
            "input_diagnostics_contract_sha256": input_diagnostics_contract_sha256.clone(),
            "input_diagnostics_negative_fixture_sha256": input_diagnostics_negative_fixture_sha256.clone(),
        },
        "compiler_boundary": &replay.compiler_boundary,
        "completed_promotion_class": &replay.completed_promotion_class,
        "next_missing_stable_promotion_class": &replay.next_missing_stable_promotion_class,
    })
}

