fn syntax_parser_or_grammar_identity(sidecar: &GrammarStructuralModelSidecar) -> Value {
    sidecar
        .input
        .provenance
        .parser
        .as_ref()
        .map(|parser| {
            json!({
                "kind": "parser",
                "tool": &parser.tool,
                "version": &parser.version,
                "package": &parser.package,
                "package_version": &parser.package_version,
            })
        })
        .unwrap_or_else(|| {
            json!({
                "kind": "grammar",
                "grammar_id": &sidecar.input.grammar_id,
                "grammar_version": sidecar.input.grammar_version,
            })
        })
}

fn token_layout_envelope_metadata(token_layout: &GrammarStructuralTokenLayout) -> Value {
    let bpe_boundary = token_layout
        .reserve_bpe_boundary(0)
        .expect("syntax token layout should reserve an empty BPE boundary");
    let structural_ranges = token_layout
        .ranges
        .iter()
        .filter(|range| range.role == "structural_decisions")
        .collect::<Vec<_>>();
    let payload_ranges = token_layout
        .ranges
        .iter()
        .filter(|range| range.role != "structural_decisions")
        .collect::<Vec<_>>();

    json!({
        "pad_token": token_layout.pad_token,
        "vocab_size": token_layout.vocab_size,
        "raw_base_vocab_size": token_layout.raw_base_vocab_size(),
        "structural_ranges": structural_ranges,
        "payload_ranges": payload_ranges,
        "bpe_boundary": {
            "raw_base_vocab_size": bpe_boundary.raw_base_vocab_size,
            "bpe_start": bpe_boundary.bpe_start,
            "bpe_end_exclusive": bpe_boundary.bpe_end_exclusive,
            "bpe_merges": bpe_boundary.bpe_merges,
            "pad_token": bpe_boundary.pad_token,
            "vocab_size": bpe_boundary.vocab_size,
            "current_layout_hosts_bpe": bpe_boundary.current_layout_hosts_bpe,
        },
    })
}

fn boundary_manifest_handoff_metadata(
    target: &str,
    grammar: &GrammarIr,
    sidecar: &GrammarStructuralModelSidecar,
    manifest: &Value,
) -> Value {
    assert_eq!(
        manifest["artifact_kind"],
        "tct_syntax_structural_model_boundary_manifest"
    );
    assert_eq!(manifest["version"], 1);
    assert_eq!(manifest["sidecar_boundary"], "GrammarIR -> StructuralModel");

    let targets = manifest["targets"]
        .as_array()
        .expect("syntax StructuralModel manifest targets must be an array");
    let target_ids = targets
        .iter()
        .map(|entry| {
            entry["target"]
                .as_str()
                .expect("syntax StructuralModel manifest target id must be a string")
        })
        .collect::<Vec<_>>();
    let target_manifest = targets
        .iter()
        .find(|entry| entry["target"] == target)
        .unwrap_or_else(|| panic!("missing syntax StructuralModel manifest target {target}"));

    let target_handoff = if target_manifest["grammar_id"] == grammar.grammar_id {
        assert_eq!(
            target_manifest["source_kind"],
            grammar.provenance.source_kind
        );
        assert_eq!(target_manifest["model_version"], sidecar.model_version);
        assert_eq!(
            target_manifest["boundary"]["generated_json_schema_output_changed"],
            json!(
                sidecar
                    .structural_model
                    .boundary
                    .generated_json_schema_output_changed
            )
        );
        assert_eq!(
            target_manifest["boundary"]["core_compiler_path_changed"],
            json!(sidecar.structural_model.boundary.core_compiler_path_changed)
        );
        assert_eq!(
            target_manifest["boundary"]["production_grammar_compiler_path_changed"],
            json!(
                sidecar
                    .structural_model
                    .boundary
                    .production_grammar_compiler_path_changed
            )
        );
        match &grammar.provenance.parser {
            Some(parser) => assert_eq!(target_manifest["parser"]["tool"], parser.tool),
            None => assert!(target_manifest["parser"].is_null()),
        }
        json!({
            "target": target,
            "source_kind": target_manifest["source_kind"].clone(),
            "grammar_id": target_manifest["grammar_id"].clone(),
            "source_path": target_manifest["source_path"].clone(),
            "source_sha256": target_manifest["source_sha256"].clone(),
            "metadata_path": target_manifest["metadata_path"].clone(),
            "metadata_sha256": target_manifest["metadata_sha256"].clone(),
            "model_version": target_manifest["model_version"].clone(),
            "parser": target_manifest["parser"].clone(),
            "boundary": target_manifest["boundary"].clone(),
            "token_range_roles": target_manifest["token_range_roles"].clone(),
            "target_manifest_sha256": json_sha256(target_manifest)
                .expect("failed to hash syntax StructuralModel manifest target"),
        })
    } else {
        assert!(
            parser_backed_construct_specific_sidecar(sidecar).is_some(),
            "construct-specific sidecars synthesize boundary manifest handoff metadata"
        );
        assert_eq!(
            grammar.provenance.source_kind,
            format!("{target}_syntax_metadata")
        );
        let parser = grammar
            .provenance
            .parser
            .as_ref()
            .expect("construct metadata must carry parser provenance");
        assert_eq!(
            parser.tool,
            if target == "csharp" { "dotnet" } else { target }
        );
        let target_manifest = json!({
            "target": target,
            "source_kind": grammar.provenance.source_kind.clone(),
            "grammar_id": grammar.grammar_id.clone(),
            "source_path": grammar.provenance.source_path.clone(),
            "source_sha256": grammar.provenance.source_sha256.clone(),
            "metadata_path": grammar.provenance.metadata_path.clone(),
            "metadata_sha256": grammar.provenance.metadata_sha256.clone(),
            "model_version": sidecar.model_version.clone(),
            "parser": {
                "tool": parser.tool.clone(),
                "version": parser.version.clone(),
                "package": parser.package.clone(),
                "package_version": parser.package_version.clone(),
            },
            "boundary": {
                "role": sidecar.structural_model.boundary.role.clone(),
                "generated_json_schema_output_changed": sidecar
                    .structural_model
                    .boundary
                    .generated_json_schema_output_changed,
                "core_compiler_path_changed": sidecar
                    .structural_model
                    .boundary
                    .core_compiler_path_changed,
                "production_grammar_compiler_path_changed": sidecar
                    .structural_model
                    .boundary
                    .production_grammar_compiler_path_changed,
            },
            "token_range_roles": sidecar
                .structural_model
                .token_ranges
                .ranges
                .iter()
                .map(|range| range.role.as_str())
                .collect::<Vec<_>>(),
        });
        let mut handoff = target_manifest.clone();
        handoff["target_manifest_sha256"] = json!(
            json_sha256(&target_manifest)
                .unwrap_or_else(|_| panic!("failed to hash {target} construct target manifest"))
        );
        handoff
    };

    json!({
        "path": STRUCTURAL_MODEL_BOUNDARY_MANIFEST_PATH,
        "artifact_kind": manifest["artifact_kind"].clone(),
        "artifact_version": manifest["version"].clone(),
        "sha256": json_sha256(manifest)
            .expect("failed to hash syntax StructuralModel boundary manifest"),
        "sidecar_boundary": manifest["sidecar_boundary"].clone(),
        "target_ids": target_ids,
        "compiler_boundary_claim": manifest["compiler_boundary_claim"].clone(),
        "target": target_handoff,
    })
}

