pub const GENERATED_CODEC_PAYLOAD_TOKEN_METADATA_SOURCE: &str =
    "src/syntax_generated_codec.rs::generated_codec_payload_token_metadata";

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct GeneratedCodecPayloadTokenMetadata {
    pub generated_codec: String,
    pub metadata_source: String,
    pub payload_end_token_source: String,
    pub structural_token_start: u32,
    pub structural_token_end_exclusive: u32,
    pub payload_end_raw_token_id: u32,
    pub utf8_byte_token_start: u32,
    pub utf8_byte_token_end_exclusive: u32,
    pub utf8_byte_token_count: usize,
}

pub fn generated_codec_payload_token_metadata(
    generated_codec: &str,
) -> Option<GeneratedCodecPayloadTokenMetadata> {
    match generated_codec {
        "go_crypto_sysrand_rand_windows_source_file_syntax_v0"
        | "go_crypto_subtle_xor_source_file_syntax_v0"
        | "go_strings_clone_source_file_syntax_v0"
        | "go_strings_compare_source_file_syntax_v0" => go_payload_token_metadata(
            generated_codec,
            GO_STRINGS_COMPARE_SOURCE_FILE_PAYLOAD_END_OFFSET,
        ),
        "go_sort_interface_source_file_syntax_v0" => {
            go_payload_token_metadata(generated_codec, GO_SOURCE_FILE_PREFIX_PAYLOAD_END_OFFSET)
        }
        "go_strings_search_source_file_syntax_v0" => {
            go_payload_token_metadata(generated_codec, GO_STRINGS_SEARCH_PAYLOAD_END_OFFSET)
        }
        "go_path_match_source_file_syntax_v0" => {
            go_payload_token_metadata(generated_codec, GO_PATH_MATCH_PAYLOAD_END_OFFSET)
        }
        "go_sort_search_source_file_syntax_v0" => {
            go_payload_token_metadata(generated_codec, GO_SORT_SEARCH_PAYLOAD_END_OFFSET)
        }
        "go_local_integer_return_literal_syntax_v0"
        | "go_local_string_return_literal_syntax_v0" => {
            go_payload_token_metadata(generated_codec, GO_RETURN_LITERAL_PAYLOAD_END_OFFSET)
        }
        "csharp_minimal_class_syntax_v0"
        | "csharp_local_string_return_literal_syntax_v0"
        | "csharp_local_integer_return_literal_syntax_v0"
        | "csharp_local_boolean_return_literal_syntax_v0"
        | "csharp_local_null_return_literal_syntax_v0"
        | "csharp_local_nullable_return_type_syntax_v0" => {
            csharp_payload_token_metadata(generated_codec, CSHARP_PAYLOAD_END_OFFSET)
        }
        "csharp_local_nullable_declaration_syntax_v0" => csharp_payload_token_metadata(
            generated_codec,
            CSHARP_LOCAL_TYPED_DECLARATION_PAYLOAD_END_OFFSET,
        ),
        "csharp_nullable_property_declaration_syntax_v0" => {
            csharp_payload_token_metadata(generated_codec, CSHARP_PAYLOAD_END_OFFSET)
        }
        "csharp_nullable_parameter_declaration_syntax_v0" => {
            csharp_payload_token_metadata(generated_codec, CSHARP_PAYLOAD_END_OFFSET)
        }
        "csharp_compilation_unit_source_file_syntax_v0" => {
            csharp_payload_token_metadata(generated_codec, CSHARP_PAYLOAD_END_OFFSET)
        }
        "csharp_compilation_unit_logger_source_file_syntax_v0" => {
            csharp_payload_token_metadata(generated_codec, CSHARP_PAYLOAD_END_OFFSET)
        }
        "csharp_compilation_unit_version_one_source_file_syntax_v0" => {
            csharp_payload_token_metadata(generated_codec, CSHARP_PAYLOAD_END_OFFSET)
        }
        "csharp_compilation_unit_iterator_methods_source_file_syntax_v0" => {
            csharp_payload_token_metadata(generated_codec, CSHARP_PAYLOAD_END_OFFSET)
        }
        "csharp_compilation_unit_loan_source_file_syntax_v0" => {
            csharp_payload_token_metadata(generated_codec, CSHARP_PAYLOAD_END_OFFSET)
        }
        _ => None,
    }
}

pub const GENERATED_CODEC_PREFIX_STATE_API_METADATA_SOURCE: &str =
    "src/syntax_generated_codec.rs::generated_codec_prefix_state_api_metadata";
pub const GENERATED_CODEC_PREFIX_STATE_API_VERSION: u32 = 1;
pub const GENERATED_CODEC_PREFIX_STATE_API_SCOPE: &str = "strict_decode_eof_prefix_state_v1";

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct GeneratedCodecPrefixStateApiMetadata {
    pub generated_codec: String,
    pub metadata_source: String,
    pub api_name: String,
    pub api_version: u32,
    pub api_scope: String,
    pub strict_decode_function: String,
    pub live_prefix_rule_source: String,
}

pub fn generated_codec_prefix_state_api_metadata(
    generated_codec: &str,
) -> Option<GeneratedCodecPrefixStateApiMetadata> {
    let (api_name, strict_decode_function) = match generated_codec {
        "go_strings_compare_source_file_syntax_v0" => (
            "decode_strings_compare_source_file_prefix_state",
            "decode_strings_compare_source_file",
        ),
        "go_sort_search_source_file_syntax_v0" => (
            "decode_sort_search_example_prefix_state",
            "decode_sort_search_example",
        ),
        "go_net_lookup_plan9_source_file_syntax_v0"
        | "go_syscall_fs_js_source_file_syntax_v0"
        | "go_os_signal_source_file_syntax_v0"
        | "go_httptest_server_source_file_syntax_v0"
        | "go_net_nss_source_file_syntax_v0"
        | "go_os_dir_unix_source_file_syntax_v0"
        | "go_net_rpc_client_source_file_syntax_v0"
        | "go_internal_coverage_cfile_testsupport_source_file_syntax_v0"
        | "go_net_ipsock_plan9_source_file_syntax_v0"
        | "go_go_ast_commentmap_source_file_syntax_v0" => (
            "target_neutral_go_source_instance_prefix_state_continuation_contract",
            "target_neutral_go_source_instance_strict_decode",
        ),
        "go_type_spec_assign_syntax_v0" => (
            "decode_integer_return_literal_prefix_state",
            "decode_integer_return_literal",
        ),
        "csharp_local_nullable_return_type_syntax_v0" => (
            "decode_local_string_return_literal_prefix_state",
            "decode_local_string_return_literal",
        ),
        "csharp_compilation_unit_source_file_syntax_v0"
        | "csharp_compilation_unit_logger_source_file_syntax_v0"
        | "csharp_compilation_unit_version_one_source_file_syntax_v0"
        | "csharp_compilation_unit_iterator_methods_source_file_syntax_v0"
        | "csharp_compilation_unit_loan_source_file_syntax_v0" => (
            "decode_compilation_unit_source_file_prefix_state",
            "decode_compilation_unit_source_file",
        ),
        _ => return None,
    };
    Some(GeneratedCodecPrefixStateApiMetadata {
        generated_codec: generated_codec.to_string(),
        metadata_source: GENERATED_CODEC_PREFIX_STATE_API_METADATA_SOURCE.to_string(),
        api_name: api_name.to_string(),
        api_version: GENERATED_CODEC_PREFIX_STATE_API_VERSION,
        api_scope: GENERATED_CODEC_PREFIX_STATE_API_SCOPE.to_string(),
        strict_decode_function: strict_decode_function.to_string(),
        live_prefix_rule_source: if matches!(
            generated_codec,
            "go_net_lookup_plan9_source_file_syntax_v0"
                | "go_syscall_fs_js_source_file_syntax_v0"
                | "go_os_signal_source_file_syntax_v0"
                | "go_httptest_server_source_file_syntax_v0"
                | "go_net_nss_source_file_syntax_v0"
                | "go_os_dir_unix_source_file_syntax_v0"
                | "go_net_rpc_client_source_file_syntax_v0"
                | "go_internal_coverage_cfile_testsupport_source_file_syntax_v0"
                | "go_net_ipsock_plan9_source_file_syntax_v0"
                | "go_go_ast_commentmap_source_file_syntax_v0"
                | "go_type_spec_assign_syntax_v0"
                | "csharp_local_nullable_return_type_syntax_v0"
        ) {
            "target_neutral_raw_transition_prefix_state_boundary"
        } else {
            "strict_decode_unexpected_eof_at_consumed_prefix_boundary"
        }
        .to_string(),
    })
}

fn go_payload_token_metadata(
    generated_codec: &str,
    payload_end_offset: u32,
) -> Option<GeneratedCodecPayloadTokenMetadata> {
    let layout = go_syntax_token_layout();
    let structural = layout
        .ranges
        .iter()
        .find(|range| range.role == "structural_decisions")?;
    let utf8 = layout
        .ranges
        .iter()
        .find(|range| range.role == "utf8_byte_payload")?;
    Some(GeneratedCodecPayloadTokenMetadata {
        generated_codec: generated_codec.to_string(),
        metadata_source: GENERATED_CODEC_PAYLOAD_TOKEN_METADATA_SOURCE.to_string(),
        payload_end_token_source: "generated_codec::PAYLOAD_END_TOKEN".to_string(),
        structural_token_start: structural.start,
        structural_token_end_exclusive: structural.end_exclusive,
        payload_end_raw_token_id: structural.start + payload_end_offset,
        utf8_byte_token_start: utf8.start,
        utf8_byte_token_end_exclusive: utf8.end_exclusive,
        utf8_byte_token_count: (utf8.end_exclusive - utf8.start) as usize,
    })
}

fn csharp_payload_token_metadata(
    generated_codec: &str,
    payload_end_offset: u32,
) -> Option<GeneratedCodecPayloadTokenMetadata> {
    let layout = csharp_syntax_token_layout();
    let structural = layout
        .ranges
        .iter()
        .find(|range| range.role == "structural_decisions")?;
    let utf8 = layout
        .ranges
        .iter()
        .find(|range| range.role == "utf8_byte_payload")?;
    Some(GeneratedCodecPayloadTokenMetadata {
        generated_codec: generated_codec.to_string(),
        metadata_source: GENERATED_CODEC_PAYLOAD_TOKEN_METADATA_SOURCE.to_string(),
        payload_end_token_source: "generated_codec::PAYLOAD_END_TOKEN".to_string(),
        structural_token_start: structural.start,
        structural_token_end_exclusive: structural.end_exclusive,
        payload_end_raw_token_id: structural.start + payload_end_offset,
        utf8_byte_token_start: utf8.start,
        utf8_byte_token_end_exclusive: utf8.end_exclusive,
        utf8_byte_token_count: (utf8.end_exclusive - utf8.start) as usize,
    })
}

