struct CSharpPayloadFieldFixtureSpec {
    field_name: &'static str,
    marker_const: &'static str,
    marker_offset: u32,
    rule: &'static str,
    fixture_value: &'static str,
}

struct CSharpPayloadCodecFixtureSpec<'a> {
    type_name: &'a str,
    encode_name: &'a str,
    decode_name: &'a str,
    recovery_name: &'a str,
    test_prefix: &'a str,
    extra_tests: &'a str,
}

fn render_csharp_payload_sequence_codec_fixture(
    sidecar: &GrammarStructuralModelSidecar,
    type_name: &str,
    encode_name: &str,
    decode_name: &str,
    recovery_name: &str,
    test_prefix: &str,
    fields: &[CSharpPayloadFieldFixtureSpec],
) -> String {
    render_csharp_payload_sequence_codec_fixture_with_extra_tests(
        sidecar,
        CSharpPayloadCodecFixtureSpec {
            type_name,
            encode_name,
            decode_name,
            recovery_name,
            test_prefix,
            extra_tests: "",
        },
        fields,
    )
}

fn render_csharp_payload_sequence_codec_fixture_with_extra_tests(
    sidecar: &GrammarStructuralModelSidecar,
    fixture: CSharpPayloadCodecFixtureSpec<'_>,
    fields: &[CSharpPayloadFieldFixtureSpec],
) -> String {
    let structural = token_range_by_role(sidecar, "structural_decisions");
    let utf8_payload = token_range_by_role(sidecar, "utf8_byte_payload");
    let marker_consts = fields
        .iter()
        .map(|field| {
            format!(
                "pub const {}: u32 = STRUCTURAL_TOKEN_START + {};",
                field.marker_const, field.marker_offset
            )
        })
        .collect::<Vec<_>>()
        .join("\n");
    let field_defs = fields
        .iter()
        .map(|field| format!("    pub {}: String,", field.field_name))
        .collect::<Vec<_>>()
        .join("\n");
    let encode_pushes = fields
        .iter()
        .map(|field| {
            format!(
                "    push_payload_field({}, &syntax.{}, &mut tokens)?;",
                field.marker_const, field.field_name
            )
        })
        .collect::<Vec<_>>()
        .join("\n");
    let decode_reads = fields
        .iter()
        .map(|field| {
            format!(
                "    let {field_name} = read_payload_field(tokens, &mut position, {marker_const}, {rule})\n        .map_err(|error| error.with_partial_fields(decoded_fields))?;\n    decoded_fields += 1;",
                field_name = field.field_name,
                marker_const = field.marker_const,
                rule = rust_string_literal(field.rule)
            )
        })
        .collect::<Vec<_>>()
        .join("\n");
    let decode_struct_fields = fields
        .iter()
        .map(|field| format!("            {},", field.field_name))
        .collect::<Vec<_>>()
        .join("\n");
    let fixture_fields = fields
        .iter()
        .map(|field| {
            format!(
                "        {}: {}.to_string(),",
                field.field_name,
                rust_string_literal(field.fixture_value)
            )
        })
        .collect::<Vec<_>>()
        .join("\n");
    let first_field = fields
        .first()
        .expect("C# payload sequence fixtures must have at least one field");
    let first_fixture_byte = first_field
        .fixture_value
        .as_bytes()
        .first()
        .copied()
        .expect("C# payload sequence fixture values must not be empty");

    format!(
        r#"#![allow(dead_code)]

pub const FRONTEND_ID: &str = {frontend_id};
pub const MODEL_ID: &str = {model_id};
pub const VOCAB_SIZE: u32 = {vocab_size};
pub const PAD_TOKEN: u32 = {pad_token};
pub const STRUCTURAL_TOKEN_START: u32 = {structural_start};
pub const STRUCTURAL_TOKEN_END: u32 = {structural_end};
pub const UTF8_BYTE_TOKEN_START: u32 = {utf8_start};
pub const UTF8_BYTE_TOKEN_END: u32 = {utf8_end};
pub const PROGRAM_START_TOKEN: u32 = STRUCTURAL_TOKEN_START + {program_start_offset};
{marker_consts}
pub const PAYLOAD_END_TOKEN: u32 = STRUCTURAL_TOKEN_START + {payload_end_offset};
pub const PROGRAM_END_TOKEN: u32 = STRUCTURAL_TOKEN_START + {program_end_offset};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SyntaxCodecError {{
    pub rule: &'static str,
    pub message: String,
    pub consumed: usize,
    pub partial_fields: usize,
}}

impl SyntaxCodecError {{
    fn new(rule: &'static str, message: impl Into<String>) -> Self {{
        Self::with_consumed(rule, message, 0)
    }}

    fn with_consumed(rule: &'static str, message: impl Into<String>, consumed: usize) -> Self {{
        Self {{
            rule,
            message: message.into(),
            consumed,
            partial_fields: 0,
        }}
    }}

    fn with_partial_fields(mut self, partial_fields: usize) -> Self {{
        self.partial_fields = partial_fields;
        self
    }}
}}

impl std::fmt::Display for SyntaxCodecError {{
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {{
        write!(formatter, "{{}}: {{}}", self.rule, self.message)
    }}
}}

impl std::error::Error for SyntaxCodecError {{}}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct {type_name} {{
{field_defs}
}}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DecodeResult {{
    pub syntax: {type_name},
    pub consumed: usize,
}}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RecoveryDecodeResult {{
    Strict(DecodeResult),
    NormalizedTrailingPad {{
        result: DecodeResult,
        ignored_trailing_tokens: usize,
    }},
    HardError(SyntaxCodecError),
}}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PrefixStateDecodeResult {{
    pub valid_prefix: bool,
    pub complete: bool,
    pub consumed: usize,
    pub rule: Option<&'static str>,
    pub message: Option<String>,
    pub partial_fields: usize,
}}

pub const GENERATED_CODEC_PREFIX_STATE_API_VERSION: u32 = 1;
pub const GENERATED_CODEC_PREFIX_STATE_API_SCOPE: &str = "strict_decode_eof_prefix_state_v1";

pub const PARSER_BACKED_RECOVERY_DECODE_POLICY: &str =
    "syntax-parser-backed-recovery-v1: strict decode is authoritative; recovery may normalize only trailing PAD_TOKENs after a complete syntax prefix; EOF, malformed structural tokens, malformed payload tokens, invalid identifiers, and partial-prefix failures remain hard errors with consumed-token and partial-result accounting";

pub fn {encode_name}(
    syntax: &{type_name},
) -> Result<Vec<u32>, SyntaxCodecError> {{
    let mut tokens = vec![PROGRAM_START_TOKEN];
{encode_pushes}
    tokens.push(PROGRAM_END_TOKEN);
    validate_tokens(&tokens)?;
    Ok(tokens)
}}

pub fn {decode_name}(tokens: &[u32]) -> Result<DecodeResult, SyntaxCodecError> {{
    let mut position = 0;
    let mut decoded_fields = 0;
    expect_token(tokens, &mut position, PROGRAM_START_TOKEN, "program_start")
        .map_err(|error| error.with_partial_fields(decoded_fields))?;
{decode_reads}
    expect_token(tokens, &mut position, PROGRAM_END_TOKEN, "program_end")
        .map_err(|error| error.with_partial_fields(decoded_fields))?;
    if position != tokens.len() {{
        return Err(SyntaxCodecError::with_consumed(
            "trailing_tokens",
            format!("decoded {{position}} of {{}} tokens", tokens.len()),
            position,
        )
        .with_partial_fields(decoded_fields));
    }}
    Ok(DecodeResult {{
        syntax: {type_name} {{
{decode_struct_fields}
        }},
        consumed: position,
    }})
}}

pub fn {decode_name}_prefix_state(tokens: &[u32]) -> PrefixStateDecodeResult {{
    match {decode_name}(tokens) {{
        Ok(result) => PrefixStateDecodeResult {{
            valid_prefix: true,
            complete: true,
            consumed: result.consumed,
            rule: None,
            message: None,
            partial_fields: 0,
        }},
        Err(error) => prefix_state_from_strict_decode_error(tokens.len(), error),
    }}
}}

fn prefix_state_from_strict_decode_error(
    token_count: usize,
    error: SyntaxCodecError,
) -> PrefixStateDecodeResult {{
    let valid_prefix =
        error.message == "unexpected end of token stream" && error.consumed == token_count;
    PrefixStateDecodeResult {{
        valid_prefix,
        complete: false,
        consumed: error.consumed,
        rule: Some(error.rule),
        message: Some(error.message),
        partial_fields: error.partial_fields,
    }}
}}

pub fn {recovery_name}(tokens: &[u32]) -> RecoveryDecodeResult {{
    match {decode_name}(tokens) {{
        Ok(result) => RecoveryDecodeResult::Strict(result),
        Err(error)
            if error.rule == "trailing_tokens"
                && tokens
                    .get(error.consumed..)
                    .is_some_and(|trailing| trailing.iter().all(|token| *token == PAD_TOKEN)) =>
        {{
            match {decode_name}(&tokens[..error.consumed]) {{
                Ok(result) => RecoveryDecodeResult::NormalizedTrailingPad {{
                    result,
                    ignored_trailing_tokens: tokens.len() - error.consumed,
                }},
                Err(error) => RecoveryDecodeResult::HardError(error),
            }}
        }}
        Err(error) => RecoveryDecodeResult::HardError(error),
    }}
}}

fn push_payload_field(
    marker: u32,
    value: &str,
    tokens: &mut Vec<u32>,
) -> Result<(), SyntaxCodecError> {{
    tokens.push(marker);
    for byte in value.as_bytes() {{
        tokens.push(UTF8_BYTE_TOKEN_START + u32::from(*byte));
    }}
    tokens.push(PAYLOAD_END_TOKEN);
    Ok(())
}}

fn read_payload_field(
    tokens: &[u32],
    position: &mut usize,
    marker: u32,
    rule: &'static str,
) -> Result<String, SyntaxCodecError> {{
    expect_token(tokens, position, marker, rule)?;
    let mut bytes = Vec::new();
    loop {{
        let token = next_token(tokens, position, rule)?;
        if token == PAYLOAD_END_TOKEN {{
            return String::from_utf8(bytes).map_err(|error| {{
                SyntaxCodecError::with_consumed(
                    rule,
                    format!("payload is not valid UTF-8: {{error}}"),
                    *position,
                )
            }});
        }}
        if !(UTF8_BYTE_TOKEN_START..UTF8_BYTE_TOKEN_END).contains(&token) {{
            return Err(SyntaxCodecError::with_consumed(
                rule,
                format!("payload token {{token}} is outside the UTF-8 range"),
                *position,
            ));
        }}
        bytes.push((token - UTF8_BYTE_TOKEN_START) as u8);
    }}
}}

fn expect_token(
    tokens: &[u32],
    position: &mut usize,
    expected: u32,
    rule: &'static str,
) -> Result<(), SyntaxCodecError> {{
    let actual = next_token(tokens, position, rule)?;
    if actual == expected {{
        Ok(())
    }} else {{
        Err(SyntaxCodecError::with_consumed(
            rule,
            format!("expected token {{expected}}, got {{actual}}"),
            *position,
        ))
    }}
}}

fn next_token(
    tokens: &[u32],
    position: &mut usize,
    rule: &'static str,
) -> Result<u32, SyntaxCodecError> {{
    let Some(token) = tokens.get(*position).copied() else {{
        return Err(SyntaxCodecError::with_consumed(
            rule,
            "unexpected end of token stream",
            *position,
        ));
    }};
    *position += 1;
    Ok(token)
}}

fn validate_tokens(tokens: &[u32]) -> Result<(), SyntaxCodecError> {{
    if let Some(token) = tokens.iter().find(|token| **token >= VOCAB_SIZE || **token == PAD_TOKEN) {{
        return Err(SyntaxCodecError::new(
            "token_bounds",
            format!("token {{token}} collides with PAD or exceeds VOCAB_SIZE"),
        ));
    }}
    Ok(())
}}

fn fixture() -> {type_name} {{
    {type_name} {{
{fixture_fields}
    }}
}}

fn main() -> Result<(), Box<dyn std::error::Error>> {{
    let syntax = fixture();
    let tokens = {encode_name}(&syntax)?;
    let decoded = {decode_name}(&tokens)?;
    assert_eq!(decoded.syntax, syntax);
    Ok(())
}}

#[cfg(test)]
mod tests {{
    use super::*;

    #[test]
    fn {test_prefix}_round_trips() {{
        let syntax = fixture();
        let tokens = {encode_name}(&syntax).unwrap();
        let decoded = {decode_name}(&tokens).unwrap();
        assert_eq!(decoded.consumed, tokens.len());
        assert_eq!(decoded.syntax, syntax);
    }}

    #[test]
    fn generated_csharp_strict_decode_rejects_eof_with_accounting() {{
        let error = {decode_name}(&[PROGRAM_START_TOKEN, {first_marker_const}]).unwrap_err();
        assert_eq!(error.rule, {first_rule});
        assert_eq!(error.consumed, 2);
        assert_eq!(error.partial_fields, 0);
    }}

    #[test]
    fn generated_csharp_strict_decode_rejects_trailing_tokens() {{
        let syntax = fixture();
        let mut tokens = {encode_name}(&syntax).unwrap();
        tokens.push(PAD_TOKEN);
        let error = {decode_name}(&tokens).unwrap_err();
        assert_eq!(error.rule, "trailing_tokens");
        assert_eq!(error.consumed, tokens.len() - 1);
        assert_eq!(error.partial_fields, {field_count});
    }}

    #[test]
    fn generated_csharp_strict_decode_rejects_malformed_payload() {{
        let syntax = fixture();
        let mut tokens = {encode_name}(&syntax).unwrap();
        let first_namespace_byte = tokens
            .iter()
            .position(|token| *token == UTF8_BYTE_TOKEN_START + u32::from({first_fixture_byte}u8))
            .unwrap();
        tokens[first_namespace_byte] = PROGRAM_END_TOKEN;
        let error = {decode_name}(&tokens).unwrap_err();
        assert_eq!(error.rule, {first_rule});
        assert_eq!(error.consumed, first_namespace_byte + 1);
        assert_eq!(error.partial_fields, 0);
    }}

    #[test]
    fn generated_csharp_recovery_normalizes_trailing_pad_only() {{
        assert_eq!(
            PARSER_BACKED_RECOVERY_DECODE_POLICY,
            "syntax-parser-backed-recovery-v1: strict decode is authoritative; recovery may normalize only trailing PAD_TOKENs after a complete syntax prefix; EOF, malformed structural tokens, malformed payload tokens, invalid identifiers, and partial-prefix failures remain hard errors with consumed-token and partial-result accounting"
        );
        let syntax = fixture();
        let mut tokens = {encode_name}(&syntax).unwrap();
        tokens.extend([PAD_TOKEN, PAD_TOKEN]);
        match {recovery_name}(&tokens) {{
            RecoveryDecodeResult::NormalizedTrailingPad {{
                result,
                ignored_trailing_tokens,
            }} => {{
                assert_eq!(result.syntax, syntax);
                assert_eq!(result.consumed, tokens.len() - ignored_trailing_tokens);
                assert_eq!(ignored_trailing_tokens, 2);
            }}
            other => panic!("expected trailing PAD normalization, got {{other:?}}"),
        }}
    }}

    #[test]
    fn generated_csharp_recovery_keeps_partial_prefix_hard() {{
        match {recovery_name}(&[PROGRAM_START_TOKEN, {first_marker_const}]) {{
            RecoveryDecodeResult::HardError(error) => {{
                assert_eq!(error.rule, {first_rule});
                assert_eq!(error.consumed, 2);
                assert_eq!(error.partial_fields, 0);
            }}
            other => panic!("expected hard partial-prefix error, got {{other:?}}"),
        }}
    }}

    #[test]
    fn {test_prefix}_prefix_state_accepts_selected_live_continuations() {{
        assert_eq!(GENERATED_CODEC_PREFIX_STATE_API_VERSION, 1);
        assert_eq!(
            GENERATED_CODEC_PREFIX_STATE_API_SCOPE,
            "strict_decode_eof_prefix_state_v1"
        );
        let first = {decode_name}_prefix_state(&[PROGRAM_START_TOKEN]);
        assert!(first.valid_prefix);
        assert!(!first.complete);
        assert_eq!(first.consumed, 1);
        assert_eq!(first.rule, Some({first_rule}));
        assert_eq!(
            first.message.as_deref(),
            Some("unexpected end of token stream")
        );
        assert_eq!(first.partial_fields, 0);

        let post_positive = {decode_name}_prefix_state(&[PROGRAM_START_TOKEN, {first_marker_const}]);
        assert!(post_positive.valid_prefix);
        assert!(!post_positive.complete);
        assert_eq!(post_positive.consumed, 2);
        assert_eq!(post_positive.rule, Some({first_rule}));
        assert_eq!(
            post_positive.message.as_deref(),
            Some("unexpected end of token stream")
        );
    }}
{extra_tests}
}}
"#,
        frontend_id = rust_string_literal(&sidecar.structural_model.frontend_id),
        model_id = rust_string_literal(&sidecar.structural_model.model_id),
        vocab_size = sidecar.structural_model.token_ranges.vocab_size,
        pad_token = sidecar.structural_model.token_ranges.pad_token,
        structural_start = structural.start,
        structural_end = structural.end_exclusive,
        utf8_start = utf8_payload.start,
        utf8_end = utf8_payload.end_exclusive,
        program_start_offset = CSHARP_PROGRAM_START_OFFSET,
        marker_consts = marker_consts,
        payload_end_offset = CSHARP_PAYLOAD_END_OFFSET,
        program_end_offset = CSHARP_PROGRAM_END_OFFSET,
        type_name = fixture.type_name,
        field_defs = field_defs,
        encode_name = fixture.encode_name,
        decode_name = fixture.decode_name,
        recovery_name = fixture.recovery_name,
        encode_pushes = encode_pushes,
        decode_reads = decode_reads,
        decode_struct_fields = decode_struct_fields,
        fixture_fields = fixture_fields,
        test_prefix = fixture.test_prefix,
        first_marker_const = first_field.marker_const,
        first_rule = rust_string_literal(first_field.rule),
        first_fixture_byte = first_fixture_byte,
        field_count = fields.len(),
        extra_tests = fixture.extra_tests,
    )
}

struct CSharpRealSourceReportTestSpec<'a> {
    test_name: &'a str,
    env_var: &'a str,
    source_path: &'a str,
    source_sha256: &'a str,
    expected_payload_sequence_token_count: usize,
    baseline_byte_token_count: usize,
    replay_label: &'a str,
    retarget_tct_tokens_to_structural_replay: bool,
}

struct CSharpRealSourceReplayReportMetadata {
    structural_replay_json: String,
    structural_replay_raw_token_ids_json: String,
    offset_mapping_json: String,
}

fn csharp_real_source_replay_report_metadata(
    sidecar: &GrammarStructuralModelSidecar,
    replay_label: &str,
    expected_payload_sequence_token_count: usize,
    retarget_tct_tokens_to_structural_replay: bool,
) -> CSharpRealSourceReplayReportMetadata {
    let structural_replay =
        crate::syntax_state_machine_replay::build_csharp_structural_replay_token_stream_from_sidecar(
            sidecar,
        )
        .unwrap_or_else(|error| {
            panic!("C# {replay_label} structural replay stream should build from sidecar: {error}")
        });
    let structural_replay_json =
        serde_json::to_string(&structural_replay).unwrap_or_else(|error| {
            panic!("C# {replay_label} structural replay stream should serialize: {error}")
        });
    let structural_replay_raw_token_ids_json =
        serde_json::to_string(&structural_replay.raw_token_ids).unwrap_or_else(|error| {
            panic!("C# {replay_label} structural replay raw tokens should serialize: {error}")
        });
    let offset_mapping = if retarget_tct_tokens_to_structural_replay {
        json!({
            "mapping_kind": "retargeted_structural_replay_stream_offsets",
            "authoritative_raw_token_stream": "tct_tokens",
            "payload_sequence_stream": "payload_sequence_control_tokens",
            "payload_sequence_token_count": expected_payload_sequence_token_count,
            "structural_replay_stream": "tct_tokens",
            "structural_replay_sidecar_stream": "structural_replay.raw_token_ids",
            "structural_replay_token_count": structural_replay.raw_token_count,
            "segment_offsets": "structural_replay.raw_token_segments.raw_token_offset",
            "payload_sequence_stream_kept_as_compatibility_control": true,
            "one_to_one_payload_sequence_offset_mapping": false
        })
    } else {
        json!({
            "mapping_kind": "sidecar_structural_replay_stream_offsets",
            "payload_sequence_stream": "tct_tokens",
            "payload_sequence_token_count": expected_payload_sequence_token_count,
            "structural_replay_stream": "structural_replay.raw_token_ids",
            "structural_replay_token_count": structural_replay.raw_token_count,
            "segment_offsets": "structural_replay.raw_token_segments.raw_token_offset",
            "payload_sequence_stream_kept_as_compatibility_control": true,
            "one_to_one_payload_sequence_offset_mapping": false
        })
    };
    let offset_mapping_json = serde_json::to_string(&offset_mapping).unwrap_or_else(|error| {
        panic!("C# {replay_label} replay offset mapping should serialize: {error}")
    });

    CSharpRealSourceReplayReportMetadata {
        structural_replay_json,
        structural_replay_raw_token_ids_json,
        offset_mapping_json,
    }
}

fn csharp_compilation_unit_real_source_report_tests(
    sidecar: &GrammarStructuralModelSidecar,
    spec: CSharpRealSourceReportTestSpec<'_>,
) -> String {
    let metadata = csharp_real_source_replay_report_metadata(
        sidecar,
        spec.replay_label,
        spec.expected_payload_sequence_token_count,
        spec.retarget_tct_tokens_to_structural_replay,
    );
    let payload_sequence_control_report_fields = if spec.retarget_tct_tokens_to_structural_replay {
        r#"            format!("  \"payload_sequence_control_token_count\": {},", tokens.len()),
            format!(
                "  \"payload_sequence_control_tokens_sha256\": {},",
                serde_json::to_string(&payload_sequence_control_tokens_sha256).unwrap()
            ),
            format!(
                "  \"payload_sequence_control_tokens\": {},",
                serde_json::to_string(tokens).unwrap()
            ),
"#
    } else {
        ""
    };
    let template = r#"

    #[test]
    fn __TEST_NAME__() {
        let syntax = fixture();
        let tokens = encode_compilation_unit_source_file(&syntax).unwrap();
        let decoded = decode_compilation_unit_source_file(&tokens).unwrap();
        assert_eq!(decoded.consumed, tokens.len());
        assert_eq!(decoded.syntax, syntax);
        assert_eq!(tokens.len(), EXPECTED_PAYLOAD_SEQUENCE_TOKEN_COUNT);
        write_real_source_generated_codec_corpus_report(&tokens);
    }

    const EXPECTED_PAYLOAD_SEQUENCE_TOKEN_COUNT: usize = __EXPECTED_PAYLOAD_SEQUENCE_TOKEN_COUNT__;
    const RETARGET_TCT_TOKENS_TO_STRUCTURAL_REPLAY: bool = __RETARGET_TCT_TOKENS_TO_STRUCTURAL_REPLAY__;
    const STRUCTURAL_REPLAY_JSON: &str = __STRUCTURAL_REPLAY_JSON__;
    const STRUCTURAL_REPLAY_RAW_TOKEN_IDS_JSON: &str = __STRUCTURAL_REPLAY_RAW_TOKEN_IDS_JSON__;
    const RAW_TOKEN_OFFSET_MAPPING_JSON: &str = __OFFSET_MAPPING_JSON__;

    fn write_real_source_generated_codec_corpus_report(tokens: &[u32]) {
        let Ok(report_path) =
            std::env::var("__ENV_VAR__")
        else {
            return;
        };
        let report_path = std::path::PathBuf::from(report_path);
        if let Some(parent) = report_path.parent() {
            std::fs::create_dir_all(parent).unwrap();
        }
        let structural_replay_tokens = structural_replay_raw_tokens();
        let report_tokens = if RETARGET_TCT_TOKENS_TO_STRUCTURAL_REPLAY {
            structural_replay_tokens.as_slice()
        } else {
            tokens
        };
        let raw_token_ids_sha256 = json_sha256_tokens(report_tokens);
        let payload_sequence_control_tokens_sha256 = json_sha256_tokens(tokens);
        let report = vec![
            "{".to_string(),
            "  \"artifact_kind\": \"tct_csharp_real_source_generated_codec_demo_v1\",".to_string(),
            "  \"version\": 1,".to_string(),
            "  \"status\": \"ready\",".to_string(),
            "  \"target\": \"csharp\",".to_string(),
            "  \"route\": \"csharp_compilation_unit_source_file_syntax_v0\",".to_string(),
            "  \"source_path\": \"__SOURCE_PATH__\",".to_string(),
            "  \"source_sha256\": \"__SOURCE_SHA256__\",".to_string(),
            "  \"corpus_manifest\": \"corpora/csharp/dotnet-samples-mini/manifest-v1.json\",".to_string(),
            "  \"generated_codec\": \"csharp_compilation_unit_source_file_syntax_v0\",".to_string(),
            "  \"generated_codec_marker\": \"generated_csharp_compilation_unit_source_file_round_trips\",".to_string(),
            format!("  \"tct_token_count\": {},", report_tokens.len()),
            format!(
                "  \"raw_token_ids_sha256\": {},",
                serde_json::to_string(&raw_token_ids_sha256).unwrap()
            ),
            format!("  \"tct_tokens\": {},", serde_json::to_string(report_tokens).unwrap()),
__PAYLOAD_SEQUENCE_CONTROL_REPORT_FIELDS__
            format!("  \"structural_replay\": {},", STRUCTURAL_REPLAY_JSON),
            format!("  \"raw_token_offset_mapping\": {},", RAW_TOKEN_OFFSET_MAPPING_JSON),
            "  \"baseline_byte_token_count\": __BASELINE_BYTE_TOKEN_COUNT__,".to_string(),
            "  \"baseline_tokenizer\": \"byte_tokenizer_257_base_vocab\",".to_string(),
            "  \"parser_validation\": {".to_string(),
            "    \"roslyn_metadata\": \"checked\"".to_string(),
            "  },".to_string(),
            "  \"compiler_boundary\": \"sidecar-only\",".to_string(),
            "  \"no_stable_promotion_claim\": \"sidecar-only real-source generated-codec evidence; no source-program validity and no stable backend promotion\",".to_string(),
            "  \"next_missing_stable_promotion_class\": \"syntax backend C# real-source generated-codec corpus gate\"".to_string(),
            "}".to_string(),
        ]
        .join("\n")
            + "\n";
        std::fs::write(report_path, report).unwrap();
    }

    fn structural_replay_raw_tokens() -> Vec<u32> {
        serde_json::from_str(STRUCTURAL_REPLAY_RAW_TOKEN_IDS_JSON).unwrap()
    }

    fn json_sha256_tokens(tokens: &[u32]) -> String {
        use sha2::Digest;

        let bytes = serde_json::to_vec(tokens).unwrap();
        let digest = sha2::Sha256::digest(&bytes);
        hex_lower(&digest)
    }

    fn hex_lower(bytes: &[u8]) -> String {
        const HEX: &[u8; 16] = b"0123456789abcdef";
        let mut output = String::with_capacity(bytes.len() * 2);
        for byte in bytes {
            output.push(HEX[(byte >> 4) as usize] as char);
            output.push(HEX[(byte & 0x0f) as usize] as char);
        }
        output
    }
"#;
    template
        .replace("__TEST_NAME__", spec.test_name)
        .replace("__ENV_VAR__", spec.env_var)
        .replace("__SOURCE_PATH__", spec.source_path)
        .replace("__SOURCE_SHA256__", spec.source_sha256)
        .replace(
            "__EXPECTED_PAYLOAD_SEQUENCE_TOKEN_COUNT__",
            &spec.expected_payload_sequence_token_count.to_string(),
        )
        .replace(
            "__RETARGET_TCT_TOKENS_TO_STRUCTURAL_REPLAY__",
            if spec.retarget_tct_tokens_to_structural_replay {
                "true"
            } else {
                "false"
            },
        )
        .replace(
            "__BASELINE_BYTE_TOKEN_COUNT__",
            &spec.baseline_byte_token_count.to_string(),
        )
        .replace(
            "__STRUCTURAL_REPLAY_JSON__",
            &rust_string_literal(&metadata.structural_replay_json),
        )
        .replace(
            "__STRUCTURAL_REPLAY_RAW_TOKEN_IDS_JSON__",
            &rust_string_literal(&metadata.structural_replay_raw_token_ids_json),
        )
        .replace(
            "__OFFSET_MAPPING_JSON__",
            &rust_string_literal(&metadata.offset_mapping_json),
        )
        .replace(
            "__PAYLOAD_SEQUENCE_CONTROL_REPORT_FIELDS__",
            payload_sequence_control_report_fields,
        )
}

