pub const STRUCTURAL_TOKEN_END: u32 = {structural_end};
pub const UTF8_BYTE_TOKEN_START: u32 = {utf8_start};
pub const UTF8_BYTE_TOKEN_END: u32 = {utf8_end};
pub const INTEGER_TOKEN_START: u32 = {integer_start};
pub const INTEGER_TOKEN_END: u32 = {integer_end};
pub const PROGRAM_START_TOKEN: u32 = STRUCTURAL_TOKEN_START + 0;
pub const NAMESPACE_TOKEN: u32 = STRUCTURAL_TOKEN_START + 1;
pub const CLASS_TOKEN: u32 = STRUCTURAL_TOKEN_START + 2;
pub const METHOD_TOKEN: u32 = STRUCTURAL_TOKEN_START + 3;
pub const RETURN_TYPE_TOKEN: u32 = STRUCTURAL_TOKEN_START + 4;
pub const LOCAL_TYPE_TOKEN: u32 = STRUCTURAL_TOKEN_START + 5;
