        let first_namespace_byte = tokens
            .iter()
            .position(|token| *token == UTF8_BYTE_TOKEN_START + u32::from(b'T'))
            .unwrap();
        tokens[first_namespace_byte] = PROGRAM_END_TOKEN;
        let error = decode_method_invocation_return(&tokens).unwrap_err();
        assert_eq!(error.rule, "namespace");
        assert_eq!(error.consumed, first_namespace_byte + 1);
