pub const PACKAGE_NAME_TOKEN: u32 = STRUCTURAL_TOKEN_START + {package_name_offset};
pub const BUILD_FUNC_NAME_TOKEN: u32 = STRUCTURAL_TOKEN_START + {build_func_name_offset};
