pub const ELLIPSIS_TYPE_TOKEN: u32 = STRUCTURAL_TOKEN_START + {ellipsis_type_offset};
pub const PARAM_NAME_TOKEN: u32 = STRUCTURAL_TOKEN_START + {param_name_offset};
pub const ELEMENT_TYPE_TOKEN: u32 = STRUCTURAL_TOKEN_START + {element_type_offset};
pub const CALL_SPREAD_TOKEN: u32 = STRUCTURAL_TOKEN_START + {call_spread_offset};
pub const TOTAL_FUNC_NAME_TOKEN: u32 = STRUCTURAL_TOKEN_START + {total_func_name_offset};
