pub struct SyntaxCodecError {
    pub rule: &'static str,
    pub message: String,
    pub consumed: usize,
    pub partial_fields: usize,
}

impl SyntaxCodecError {
    fn new(rule: &'static str, message: impl Into<String>) -> Self {
        Self::with_consumed(rule, message, 0)
    }

    fn with_consumed(rule: &'static str, message: impl Into<String>, consumed: usize) -> Self {
        Self {
            rule,
            message: message.into(),
            consumed,
            partial_fields: 0,
        }
    }

    fn with_partial_fields(mut self, partial_fields: usize) -> Self {
        self.partial_fields = partial_fields;
        self
    }

    fn with_consumed_position(mut self, consumed: usize) -> Self {
        self.consumed = consumed;
        self
    }
}

impl std::fmt::Display for SyntaxCodecError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(formatter, "{}: {}", self.rule, self.message)
    }
}

impl std::error::Error for SyntaxCodecError {}

