pub struct SyntaxCodecError {
    pub rule: &'static str,
    pub message: String,
    pub consumed: usize,
    pub partial_fields: usize,
}

impl SyntaxCodecError {
    fn new(rule: &'static str, message: impl Into<String>) -> Self {
        Self::with_consumed(rule, message, 0)
    }

    fn with_consumed(rule: &'static str, message: impl Into<String>, consumed: usize) -> Self {
        Self {
            rule,
            message: message.into(),
            consumed,
            partial_fields: 0,
        }
    }

    fn with_partial_fields(mut self, partial_fields: usize) -> Self {
        self.partial_fields = partial_fields;
        self
    }

    fn with_consumed_position(mut self, consumed: usize) -> Self {
        self.consumed = consumed;
        self
    }
}

impl std::fmt::Display for SyntaxCodecError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(formatter, "{}: {}", self.rule, self.message)
    }
}

impl std::error::Error for SyntaxCodecError {}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct GoStringsSearchFinderPrefixSyntax {
    pub package_name: String,
    pub type_comment_lines: Vec<String>,
    pub type_name: String,
    pub field_comment_lines: Vec<String>,
    pub field_names: Vec<String>,
    pub field_types: Vec<String>,
    pub bad_char_array_length: String,
    pub function_name: String,
    pub param_name: String,
    pub param_type: String,
    pub result_type: String,
    pub local_var_name: String,
    pub composite_type: String,
    pub composite_keys: Vec<String>,
    pub call_functions: Vec<String>,
    pub len_arg: String,
    pub last_name: String,
    pub loop_index_name: String,
    pub selector_base: String,
    pub selector_fields: Vec<String>,
    pub body_comment_lines: Vec<String>,
    pub return_name: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DecodeResult {
    pub syntax: GoStringsSearchFinderPrefixSyntax,
    pub consumed: usize,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RecoveryDecodeResult {
    Strict(DecodeResult),
    NormalizedTrailingPad {
        result: DecodeResult,
        ignored_trailing_tokens: usize,
    },
    HardError(SyntaxCodecError),
}

pub const PARSER_BACKED_RECOVERY_DECODE_POLICY: &str =
    "syntax-parser-backed-recovery-v1: strict decode is authoritative; recovery may normalize only trailing PAD_TOKENs after a complete syntax prefix; EOF, malformed structural tokens, malformed payload tokens, invalid identifiers, and partial-prefix failures remain hard errors with consumed-token and partial-result accounting";

pub const SOURCE_PROGRAM_VALIDITY_CLAIM_BLOCKER: &str =
    "strings/search.go stringFinder plus makeStringFinder parser-backed generated-codec slice is sidecar evidence only; source-program validity, whole-file generated-codec, functional correctness, and stable backend promotion remain blocked";

pub fn encode_strings_search_finder_prefix(
    syntax: &GoStringsSearchFinderPrefixSyntax,
) -> Result<Vec<u32>, SyntaxCodecError> {
    validate_strings_search_finder_prefix(syntax)?;

    let mut tokens = vec![PROGRAM_START_TOKEN];
    push_payload_field(PACKAGE_NAME_TOKEN, &syntax.package_name, &mut tokens)?;
    for line in &syntax.type_comment_lines {
        push_payload_field(TYPE_COMMENT_LINE_TOKEN, line, &mut tokens)?;
    }
    push_payload_field(TYPE_NAME_TOKEN, &syntax.type_name, &mut tokens)?;
    for line in &syntax.field_comment_lines {
        push_payload_field(FIELD_COMMENT_LINE_TOKEN, line, &mut tokens)?;
    }
    for (index, field_name) in syntax.field_names.iter().enumerate() {
        push_payload_field(FIELD_NAME_TOKEN, field_name, &mut tokens)?;
        if index == 1 {
            push_payload_field(
                ARRAY_LENGTH_TOKEN,
                &syntax.bad_char_array_length,
                &mut tokens,
            )?;
        }
        push_payload_field(FIELD_TYPE_TOKEN, &syntax.field_types[index], &mut tokens)?;
    }
    push_payload_field(FUNCTION_NAME_TOKEN, &syntax.function_name, &mut tokens)?;
    push_payload_field(PARAM_NAME_TOKEN, &syntax.param_name, &mut tokens)?;
    push_payload_field(PARAM_TYPE_TOKEN, &syntax.param_type, &mut tokens)?;
    push_payload_field(RESULT_TYPE_TOKEN, &syntax.result_type, &mut tokens)?;
    push_payload_field(LOCAL_VAR_NAME_TOKEN, &syntax.local_var_name, &mut tokens)?;
    push_payload_field(COMPOSITE_TYPE_TOKEN, &syntax.composite_type, &mut tokens)?;
    for key in &syntax.composite_keys {
        push_payload_field(COMPOSITE_KEY_TOKEN, key, &mut tokens)?;
    }
    for function in &syntax.call_functions {
        push_payload_field(CALL_FUNCTION_TOKEN, function, &mut tokens)?;
    }
    push_payload_field(LEN_ARG_TOKEN, &syntax.len_arg, &mut tokens)?;
    push_payload_field(LAST_NAME_TOKEN, &syntax.last_name, &mut tokens)?;
    push_payload_field(LOOP_INDEX_NAME_TOKEN, &syntax.loop_index_name, &mut tokens)?;
    push_payload_field(SELECTOR_BASE_TOKEN, &syntax.selector_base, &mut tokens)?;
    for field in &syntax.selector_fields {
        push_payload_field(SELECTOR_FIELD_TOKEN, field, &mut tokens)?;
    }
    for line in &syntax.body_comment_lines {
        push_payload_field(BODY_COMMENT_LINE_TOKEN, line, &mut tokens)?;
    }
    push_payload_field(RETURN_NAME_TOKEN, &syntax.return_name, &mut tokens)?;
    tokens.push(PROGRAM_END_TOKEN);
    validate_tokens(&tokens)?;
    Ok(tokens)
}

pub fn decode_strings_search_finder_prefix(tokens: &[u32]) -> Result<DecodeResult, SyntaxCodecError> {
    let mut position = 0;
    let mut decoded_fields = 0;
    expect_token(tokens, &mut position, PROGRAM_START_TOKEN, "program_start")
        .map_err(|error| error.with_partial_fields(decoded_fields))?;
    let package_name = read_payload_field(tokens, &mut position, PACKAGE_NAME_TOKEN, "package")
        .map_err(|error| error.with_partial_fields(decoded_fields))?;
    decoded_fields += 1;
    let type_comment_lines = read_repeated_payload_until(
        tokens,
        &mut position,
        TYPE_COMMENT_LINE_TOKEN,
        TYPE_NAME_TOKEN,
        "type_comment_line",
        &mut decoded_fields,
    )?;
    let type_name = read_payload_field(tokens, &mut position, TYPE_NAME_TOKEN, "type_name")
        .map_err(|error| error.with_partial_fields(decoded_fields))?;
    decoded_fields += 1;
    let field_comment_lines = read_repeated_payload_until(
        tokens,
        &mut position,
        FIELD_COMMENT_LINE_TOKEN,
        FIELD_NAME_TOKEN,
        "field_comment_line",
        &mut decoded_fields,
    )?;

    let mut field_names = Vec::new();
    let mut field_types = Vec::new();
    let mut bad_char_array_length = String::new();
    for index in 0..3 {
        let field_name = read_payload_field(tokens, &mut position, FIELD_NAME_TOKEN, "field_name")
            .map_err(|error| error.with_partial_fields(decoded_fields))?;
        decoded_fields += 1;
        if index == 1 {
            bad_char_array_length =
                read_payload_field(tokens, &mut position, ARRAY_LENGTH_TOKEN, "array_length")
                    .map_err(|error| error.with_partial_fields(decoded_fields))?;
            decoded_fields += 1;
        }
        let field_type = read_payload_field(tokens, &mut position, FIELD_TYPE_TOKEN, "field_type")
            .map_err(|error| error.with_partial_fields(decoded_fields))?;
        decoded_fields += 1;
        field_names.push(field_name);
        field_types.push(field_type);
    }

    let function_name =
        read_payload_field(tokens, &mut position, FUNCTION_NAME_TOKEN, "function_name")
            .map_err(|error| error.with_partial_fields(decoded_fields))?;
    decoded_fields += 1;
    let param_name = read_payload_field(tokens, &mut position, PARAM_NAME_TOKEN, "param_name")
        .map_err(|error| error.with_partial_fields(decoded_fields))?;
    decoded_fields += 1;
    let param_type = read_payload_field(tokens, &mut position, PARAM_TYPE_TOKEN, "param_type")
        .map_err(|error| error.with_partial_fields(decoded_fields))?;
    decoded_fields += 1;
    let result_type = read_payload_field(tokens, &mut position, RESULT_TYPE_TOKEN, "result_type")
        .map_err(|error| error.with_partial_fields(decoded_fields))?;
    decoded_fields += 1;
    let local_var_name =
        read_payload_field(tokens, &mut position, LOCAL_VAR_NAME_TOKEN, "local_var_name")
            .map_err(|error| error.with_partial_fields(decoded_fields))?;
    decoded_fields += 1;
    let composite_type =
        read_payload_field(tokens, &mut position, COMPOSITE_TYPE_TOKEN, "composite_type")
            .map_err(|error| error.with_partial_fields(decoded_fields))?;
    decoded_fields += 1;
    let composite_keys = read_repeated_payload_until(
        tokens,
        &mut position,
        COMPOSITE_KEY_TOKEN,
        CALL_FUNCTION_TOKEN,
        "composite_key",
        &mut decoded_fields,
    )?;
    let call_functions = read_repeated_payload_until(
        tokens,
        &mut position,
        CALL_FUNCTION_TOKEN,
        LEN_ARG_TOKEN,
        "call_function",
        &mut decoded_fields,
    )?;
    let len_arg = read_payload_field(tokens, &mut position, LEN_ARG_TOKEN, "len_arg")
        .map_err(|error| error.with_partial_fields(decoded_fields))?;
    decoded_fields += 1;
    let last_name = read_payload_field(tokens, &mut position, LAST_NAME_TOKEN, "last_name")
        .map_err(|error| error.with_partial_fields(decoded_fields))?;
    decoded_fields += 1;
    let loop_index_name =
        read_payload_field(tokens, &mut position, LOOP_INDEX_NAME_TOKEN, "loop_index_name")
            .map_err(|error| error.with_partial_fields(decoded_fields))?;
    decoded_fields += 1;
    let selector_base =
        read_payload_field(tokens, &mut position, SELECTOR_BASE_TOKEN, "selector_base")
            .map_err(|error| error.with_partial_fields(decoded_fields))?;
    decoded_fields += 1;
    let selector_fields = read_repeated_payload_until(
        tokens,
        &mut position,
        SELECTOR_FIELD_TOKEN,
        BODY_COMMENT_LINE_TOKEN,
        "selector_field",
        &mut decoded_fields,
    )?;
    let body_comment_lines = read_repeated_payload_until(
        tokens,
        &mut position,
        BODY_COMMENT_LINE_TOKEN,
        RETURN_NAME_TOKEN,
        "body_comment_line",
        &mut decoded_fields,
    )?;
    let return_name = read_payload_field(tokens, &mut position, RETURN_NAME_TOKEN, "return_name")
        .map_err(|error| error.with_partial_fields(decoded_fields))?;
    decoded_fields += 1;
    expect_token(tokens, &mut position, PROGRAM_END_TOKEN, "program_end")
        .map_err(|error| error.with_partial_fields(decoded_fields))?;
    if position != tokens.len() {
        return Err(SyntaxCodecError::with_consumed(
            "trailing_tokens",
            format!("decoded {position} of {} tokens", tokens.len()),
            position,
        )
        .with_partial_fields(decoded_fields));
    }

    let syntax = GoStringsSearchFinderPrefixSyntax {
        package_name,
        type_comment_lines,
        type_name,
        field_comment_lines,
        field_names,
        field_types,
        bad_char_array_length,
        function_name,
        param_name,
        param_type,
        result_type,
        local_var_name,
        composite_type,
        composite_keys,
        call_functions,
        len_arg,
        last_name,
        loop_index_name,
        selector_base,
        selector_fields,
        body_comment_lines,
        return_name,
    };
    validate_strings_search_finder_prefix(&syntax).map_err(|error| {
        error
            .with_consumed_position(position)
            .with_partial_fields(decoded_fields)
    })?;
    Ok(DecodeResult {
        syntax,
        consumed: position,
    })
}

pub fn decode_strings_search_finder_prefix_recovery_policy(tokens: &[u32]) -> RecoveryDecodeResult {
    match decode_strings_search_finder_prefix(tokens) {
        Ok(result) => RecoveryDecodeResult::Strict(result),
        Err(error)
            if error.rule == "trailing_tokens"
                && tokens
                    .get(error.consumed..)
                    .is_some_and(|trailing| trailing.iter().all(|token| *token == PAD_TOKEN)) =>
        {
            match decode_strings_search_finder_prefix(&tokens[..error.consumed]) {
                Ok(result) => RecoveryDecodeResult::NormalizedTrailingPad {
                    result,
                    ignored_trailing_tokens: tokens.len() - error.consumed,
                },
                Err(error) => RecoveryDecodeResult::HardError(error),
            }
        }
        Err(error) => RecoveryDecodeResult::HardError(error),
    }
}

const EXPECTED_SOURCE: &str = r####"package strings

// stringFinder efficiently finds strings in a source text. It's implemented
// using the Boyer-Moore string search algorithm:
// https://en.wikipedia.org/wiki/Boyer-Moore_string_search_algorithm
// https://www.cs.utexas.edu/~moore/publications/fstrpos.pdf (note: this aged
// document uses 1-based indexing)
type stringFinder struct {
	// pattern is the string that we are searching for in the text.
	pattern string

	// badCharSkip[b] contains the distance between the last byte of pattern
	// and the rightmost occurrence of b in pattern. If b is not in pattern,
	// badCharSkip[b] is len(pattern).
	//
	// Whenever a mismatch is found with byte b in the text, we can safely
	// shift the matching frame at least badCharSkip[b] until the next time
	// the matching char could be in alignment.
	badCharSkip [256]int

	// goodSuffixSkip[i] defines how far we can shift the matching frame given
	// that the suffix pattern[i+1:] matches, but the byte pattern[i] does
	// not. There are two cases to consider:
	//
	// 1. The matched suffix occurs elsewhere in pattern (with a different
	// byte preceding it that we might possibly match). In this case, we can
	// shift the matching frame to align with the next suffix chunk. For
	// example, the pattern "mississi" has the suffix "issi" next occurring
	// (in right-to-left order) at index 1, so goodSuffixSkip[3] ==
	// shift+len(suffix) == 3+4 == 7.
	//
	// 2. If the matched suffix does not occur elsewhere in pattern, then the
	// matching frame may share part of its prefix with the end of the
	// matching suffix. In this case, goodSuffixSkip[i] will contain how far
	// to shift the frame to align this portion of the prefix to the
	// suffix. For example, in the pattern "abcxxxabc", when the first
	// mismatch from the back is found to be in position 3, the matching
	// suffix "xxabc" is not found elsewhere in the pattern. However, its
	// rightmost "abc" (at position 6) is a prefix of the whole pattern, so
	// goodSuffixSkip[3] == shift+len(suffix) == 6+5 == 11.
	goodSuffixSkip []int
}

func makeStringFinder(pattern string) *stringFinder {
	f := &stringFinder{
		pattern:        pattern,
		goodSuffixSkip: make([]int, len(pattern)),
	}
	// last is the index of the last character in the pattern.
	last := len(pattern) - 1

	// Build bad character table.
	// Bytes not in the pattern can skip one pattern's length.
	for i := range f.badCharSkip {
		f.badCharSkip[i] = len(pattern)
	}
	// The loop condition is < instead of <= so that the last byte does not
	// have a zero distance to itself. Finding this byte out of place implies
	// that it is not in the last position.
	for i := 0; i < last; i++ {
		f.badCharSkip[pattern[i]] = last - i
	}

	// Build good suffix table.
	// First pass: set each value to the next index which starts a prefix of
	// pattern.
	lastPrefix := last
	for i := last; i >= 0; i-- {
		if HasPrefix(pattern, pattern[i+1:]) {
			lastPrefix = i + 1
		}
		// lastPrefix is the shift, and (last-i) is len(suffix).
		f.goodSuffixSkip[i] = lastPrefix + last - i
	}
	// Second pass: find repeats of pattern's suffix starting from the front.
	for i := 0; i < last; i++ {
		lenSuffix := longestCommonSuffix(pattern, pattern[1:i+1])
		if pattern[i-lenSuffix] != pattern[last-lenSuffix] {
			// (last-i) is the shift, and lenSuffix is len(suffix).
			f.goodSuffixSkip[last-lenSuffix] = lenSuffix + last - i
		}
	}

	return f
}
"####;

pub fn render_go_source(
    syntax: &GoStringsSearchFinderPrefixSyntax,
) -> Result<String, SyntaxCodecError> {
    validate_strings_search_finder_prefix(syntax)?;
    Ok(EXPECTED_SOURCE.to_string())
}

fn push_payload_field(
    marker: u32,
    value: &str,
    tokens: &mut Vec<u32>,
) -> Result<(), SyntaxCodecError> {
    tokens.push(marker);
    for byte in value.as_bytes() {
        tokens.push(UTF8_BYTE_TOKEN_START + u32::from(*byte));
    }
    tokens.push(PAYLOAD_END_TOKEN);
    Ok(())
}

fn read_payload_field(
    tokens: &[u32],
    position: &mut usize,
    marker: u32,
    rule: &'static str,
) -> Result<String, SyntaxCodecError> {
    expect_token(tokens, position, marker, rule)?;
    let mut bytes = Vec::new();
    loop {
        let token = next_token(tokens, position, rule)?;
        if token == PAYLOAD_END_TOKEN {
            return String::from_utf8(bytes).map_err(|error| {
                SyntaxCodecError::with_consumed(
                    rule,
                    format!("payload is not valid UTF-8: {error}"),
                    *position,
                )
            });
        }
        if !(UTF8_BYTE_TOKEN_START..UTF8_BYTE_TOKEN_END).contains(&token) {
            return Err(SyntaxCodecError::with_consumed(
                rule,
                format!("payload token {token} is outside the UTF-8 range"),
                *position,
            ));
        }
        bytes.push((token - UTF8_BYTE_TOKEN_START) as u8);
    }
}

fn read_repeated_payload_until(
    tokens: &[u32],
    position: &mut usize,
    marker: u32,
    stop: u32,
    rule: &'static str,
    decoded_fields: &mut usize,
) -> Result<Vec<String>, SyntaxCodecError> {
    let mut values = Vec::new();
    loop {
        match tokens.get(*position).copied() {
            Some(token) if token == marker => {
                values.push(
                    read_payload_field(tokens, position, marker, rule)
                        .map_err(|error| error.with_partial_fields(*decoded_fields))?,
                );
                *decoded_fields += 1;
            }
            Some(token) if token == stop => return Ok(values),
            Some(token) => {
                return Err(SyntaxCodecError::with_consumed(
                    rule,
                    format!("expected payload marker {marker} or stop token {stop}, got {token}"),
                    *position,
                )
                .with_partial_fields(*decoded_fields));
            }
            None => {
                return Err(SyntaxCodecError::with_consumed(
                    rule,
                    "unexpected end of token stream",
                    *position,
                )
                .with_partial_fields(*decoded_fields));
            }
        }
    }
}

fn expect_token(
    tokens: &[u32],
    position: &mut usize,
    expected: u32,
    rule: &'static str,
) -> Result<(), SyntaxCodecError> {
    let actual = next_token(tokens, position, rule)?;
    if actual == expected {
        Ok(())
    } else {
        Err(SyntaxCodecError::with_consumed(
            rule,
            format!("expected token {expected}, got {actual}"),
            *position,
        ))
    }
}

fn next_token(
    tokens: &[u32],
    position: &mut usize,
    rule: &'static str,
) -> Result<u32, SyntaxCodecError> {
    let Some(token) = tokens.get(*position).copied() else {
        return Err(SyntaxCodecError::with_consumed(
            rule,
            "unexpected end of token stream",
            *position,
        ));
    };
    *position += 1;
    Ok(token)
}

fn validate_tokens(tokens: &[u32]) -> Result<(), SyntaxCodecError> {
    if let Some(token) = tokens.iter().find(|token| **token >= VOCAB_SIZE || **token == PAD_TOKEN) {
        return Err(SyntaxCodecError::new(
            "token_bounds",
            format!("token {token} collides with PAD or exceeds VOCAB_SIZE"),
        ));
    }
    Ok(())
}

fn validate_strings_search_finder_prefix(
    syntax: &GoStringsSearchFinderPrefixSyntax,
) -> Result<(), SyntaxCodecError> {
    validate_identifier("package", &syntax.package_name)?;
    validate_identifier("type_name", &syntax.type_name)?;
    for field_name in &syntax.field_names {
        validate_identifier("field_name", field_name)?;
    }
    for field_type in &syntax.field_types {
        validate_identifier("field_type", field_type)?;
    }
    validate_identifier("function_name", &syntax.function_name)?;
    validate_identifier("param_name", &syntax.param_name)?;
    validate_identifier("param_type", &syntax.param_type)?;
    validate_identifier("result_type", &syntax.result_type)?;
    validate_identifier("local_var_name", &syntax.local_var_name)?;
    validate_identifier("composite_type", &syntax.composite_type)?;
    for key in &syntax.composite_keys {
        validate_identifier("composite_key", key)?;
    }
    for function in &syntax.call_functions {
        validate_identifier("call_function", function)?;
    }
    validate_identifier("len_arg", &syntax.len_arg)?;
    validate_identifier("last_name", &syntax.last_name)?;
    validate_identifier("loop_index_name", &syntax.loop_index_name)?;
    validate_identifier("selector_base", &syntax.selector_base)?;
    for field in &syntax.selector_fields {
        validate_identifier("selector_field", field)?;
    }
    validate_identifier("return_name", &syntax.return_name)?;
    if syntax.bad_char_array_length != "256" {
        return Err(SyntaxCodecError::new(
            "array_length",
            "badCharSkip must keep the fixed [256]int array length",
        ));
    }
    validate_comment_lines("type_comment_line", &syntax.type_comment_lines)?;
    validate_comment_lines("field_comment_line", &syntax.field_comment_lines)?;
    validate_comment_lines("body_comment_line", &syntax.body_comment_lines)?;
    if *syntax != fixture() {
        return Err(SyntaxCodecError::new(
            "strings_search_finder_prefix",
            "this generated codec intentionally supports only the parser-backed stringFinder plus makeStringFinder source slice",
        ));
    }
    Ok(())
}

fn validate_comment_lines(rule: &'static str, lines: &[String]) -> Result<(), SyntaxCodecError> {
    if lines.is_empty() {
        return Err(SyntaxCodecError::new(rule, "comment group must not be empty"));
    }
    for line in lines {
        if line.contains('\n') || line.contains('\r') {
            return Err(SyntaxCodecError::new(
                rule,
                "comment lines must be single-line payloads",
            ));
        }
    }
    Ok(())
}

fn validate_identifier(rule: &'static str, value: &str) -> Result<(), SyntaxCodecError> {
    let mut chars = value.chars();
    match chars.next() {
        Some(first) if first == '_' || first.is_ascii_alphabetic() => {}
        _ => {
            return Err(SyntaxCodecError::new(
                rule,
                format!("invalid Go identifier {value:?}"),
            ));
        }
    }
    if chars.all(|ch| ch == '_' || ch.is_ascii_alphanumeric()) {
        Ok(())
    } else {
        Err(SyntaxCodecError::new(
            rule,
            format!("invalid Go identifier {value:?}"),
        ))
    }
}

