fn main() -> Result<(), Box<dyn std::error::Error>> {
    let syntax = fixture();
    let tokens = encode_strings_search_finder_prefix(&syntax)?;
    let decoded = decode_strings_search_finder_prefix(&tokens)?;
    assert_eq!(decoded.syntax, syntax);
    assert!(!render_go_source(&decoded.syntax)?.is_empty());
    Ok(())
}

