pub const PACKAGE_NAME_TOKEN: u32 = STRUCTURAL_TOKEN_START + {package_name_offset};
pub const FUNC_DECL_TOKEN: u32 = STRUCTURAL_TOKEN_START + {func_decl_offset};
pub const FUNC_NAME_TOKEN: u32 = STRUCTURAL_TOKEN_START + {func_name_offset};
pub const RESULT_TYPE_TOKEN: u32 = STRUCTURAL_TOKEN_START + {result_type_offset};
